 const W=k=>k.length<=2||["ut","mt","lt","lc","pc","mc"].includes(k)?3.2:["utA","utP","mtA","mtP","ltA","ltP","med","medL","medM","uln","rad","mcn","ax"].includes(k)?2.4:1.8;
 Object.entries(G.N).forEach(([k,segs])=>segs.forEach(([d,st])=>s+=seg(d,st,"var(--nerve)",W(k))));
