 s+=`<defs><clipPath id="nbcl"><rect x="0" y="0" width="190" height="430"/><rect x="240" y="0" width="200" height="430"/></clipPath></defs><g clip-path="url(#nbcl)">${bone(B.clav[0])}</g>`;
 on.forEach(k=>(G.N[k]||[]).forEach(([d,st])=>{s+=seg(d,st,"var(--pri)",W(k)+6,.3)+seg(d,st,"var(--pri)",W(k)+1)}));
 Object.entries(G.LV).forEach(([n,[x,y]])=>s+=`<text x="${x+4}" y="${y+4}" font-size="10" font-weight="700" fill="var(--mute)" text-anchor="start">${n}</text>`);
 G.LBL.forEach(([t,[x,y]])=>t.split("\n").forEach((ln,i)=>s+=`<text x="${x}" y="${y+i*11}" font-size="10" fill="var(--mute)" text-anchor="middle">${ln}</text>`));
 if(lab){Object.entries(G.MAP).filter(([m])=>!(G.NT||[]).includes(m)).forEach(([m,ks])=>ks.forEach(k=>(G.N[k]||[]).forEach(([d])=>{s+=`<path d="${d}" fill="none" stroke="var(--pri)" stroke-width="12" stroke-linecap="round" class="sfh" data-n="${G.NM[m]}" onclick="sfTap(this)" style="cursor:pointer;opacity:0"/>`})));
  if(on.length&&typeof lab==="string"){lab=G.NM[h]||lab;const fz=12,[ax,ay]=G.AN[h],LO=(G.LO||{})[h]||[0,0],w=lab.length*fz*.6+12,lx=Math.max(4,Math.min(G.W-4-w,ax-w/2+LO[0])),ly=(ay>G.H-40?ay-24:ay+28)+LO[1];
   s+=`<line x1="${ax}" y1="${ay}" x2="${lx+w/2}" y2="${ly>ay?ly-fz:ly+4}" stroke="var(--ink)" stroke-width="1.2"/><circle cx="${ax}" cy="${ay}" r="3" fill="var(--ink)"/><text x="${lx+w/2}" y="${ly}" text-anchor="middle" font-size="${fz}" font-weight="700" fill="var(--ink)" stroke="var(--card)" stroke-width="4" paint-order="stroke" style="pointer-events:none">${lab}</text>`}}
 if(!lab)s+=`<text x="${G.W/2}" y="${H-7}" text-anchor="middle" font-size="11" fill="var(--mute)">${G.cap}</text>`;
