const nbBoth=(h,t)=>`<div class="clvw"><div style="display:flex;gap:6px;justify-content:center;margin:0 0 6px"><button class="lnk clvb" aria-pressed="true" onclick="mvSw(this,0)">In place</button><button class="lnk clvb" aria-pressed="false" onclick="mvSw(this,1)">Plan</button></div><div class="clvv">${drawNB(h,t||1)}</div><div class="clvv" hidden>${drawB(NBK[h]||"",1)}</div></div>`;
