 +`<path d="${SB.d}" fill="var(--bone)" stroke="var(--mute)" stroke-width=".7" fill-rule="evenodd" stroke-linejoin="round"/>`
 +[["roots","Roots"],["trunks","Trunks"],["divs","Divisions"],["cords","Cords"]].map(([k,t])=>`<text x="${SB.hdr[k][0]}" y="10" text-anchor="middle" font-size="10" fill="var(--mute)">${t}</text>`).join("")
 +Object.entries(SB.lv).map(([n,q])=>`<text x="${q[0]+3}" y="${q[1]+4}" font-size="10" font-weight="700" fill="var(--mute)">${n}</text>`).join("");
