function palpHTML(id,i){
 const p=PALP[id][i],on=(S.pal||{})[p.t];
 return `<p class="tag">Palpate it ${i+1} of ${PALP[id].length}</p><h2>${p.t}</h2>${figL(p.fg||LEARN[id][p.g],p.t)}<ol><li><b>Position:</b> ${p.p}</li><li><b>Start:</b> ${p.s}</li><li><b>Palpate:</b> ${p.d}</li></ol><div class="cfl"><b>You should feel:</b> ${p.f}</div><div class="cfl"><b>Common mistake:</b> ${p.e}</div>${p.v?`<video controls playsinline style="width:100%;border-radius:14px;margin-bottom:10px" src="${p.v}"></video>`:`<div class="opt" style="border-style:dashed;text-align:center;color:var(--mute)">Video coming soon</div>`}<button class="opt" style="text-align:center" onclick="tick('${id}',${i})">${on?"✓ I can find this":"Mark: I can find this"}</button>`;
}
function palp(id,i,keep){
 const n=PALP[id].length;if(i==null||i<0)i=0;if(i>n-1)i=n-1;const last=i>=n-1;
 S.palAt=S.palAt||{};if(S.palAt[id]!==i){S.palAt[id]=i;save()}
 app.innerHTML=`<button class="lnk" onclick="home()">‹ Path</button>`+palpHTML(id,i)+`<div class="tabs">${i?`<button class="opt" style="text-align:center" onclick="palp('${id}',${i-1})">Previous</button>`:""}<button class="go" onclick="${last?`palpEnd('${id}')`:`palp('${id}',${i+1})`}">${last?"Done":"Next"}</button></div>`;
 if(!keep)window.scrollTo(0,0);
}
/* reopen where you left off; start again once every landmark has been done */
function palpOpen(id){const at=(S.palAt||{})[id];palp(id,at==null?0:at)}
function palpEnd(id){S.palAt=S.palAt||{};delete S.palAt[id];save();home()}
function tick(id,i){const t=PALP[id][i].t,y=window.scrollY;S.pal=S.pal||{};S.pal[t]=!S.pal[t];save();palp(id,i,true);window.scrollTo(0,y)}
