const reduced=()=>{try{return matchMedia("(prefers-reduced-motion: reduce)").matches}catch(e){return false}};
function confetti(n){try{if(reduced())return;const c=document.createElement("div");c.className="cf";const cols=["#0A1F3D","#1A6BFF","#5CA3FF","#FFC233","#2B8CE6"];let s="";for(let i=0;i<n;i++){s+=`<i style="left:${Math.random()*100}%;background:${cols[i%5]};animation-duration:${(1.6+Math.random()*1.2).toFixed(2)}s;animation-delay:${(Math.random()*.5).toFixed(2)}s;width:${6+(Math.random()*6|0)}px;height:${10+(Math.random()*8|0)}px"></i>`}c.innerHTML=s;document.body.appendChild(c);setTimeout(()=>c.remove(),3800)}catch(e){}}
let AC=null;
const snd=()=>S.snd!==0;
function ac(){try{if(!AC){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;AC=new C()}if(AC.state==="suspended")AC.resume();return AC}catch(e){return null}}
function tone(f,t0,d,ty,v){try{const c=ac();if(!c)return;const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+t0;o.type=ty||"sine";o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v||.16,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+d+.05)}catch(e){}}
const SEMI=[0,2,4,5,7,9,11,12,14];
const hapOn=()=>S.hap!==0;let HX=null;
const HPAT={ok:[12],bad:[35,60,35],mile:[15,40,15,40,30],fin:[20,60,20,60,60],on:[10],tap:[8]};
function hapTap(){try{if(!HX){HX=document.createElement("label");HX.setAttribute("aria-hidden","true");HX.style.cssText="position:fixed;left:-99px;top:0;width:1px;height:1px;opacity:0;pointer-events:none";HX.innerHTML='<input type="checkbox" switch tabindex="-1">';document.body.appendChild(HX)}HX.click()}catch(e){}}
function hap(k,n){if(!hapOn())return;let p=HPAT[k]||[10];if(k==="fin"&&(n||0)<60)p=[20];
 try{if(navigator.vibrate&&navigator.vibrate(p))return}catch(e){}
 const on=p.filter((_,i)=>i%2===0);let t=0;on.forEach((d,i)=>{if(i===0)hapTap();else setTimeout(hapTap,t);t+=d+(p[2*i+1]||0)})}
function sfx(k,n){hap(k,n);if(!snd())return;n=n||0;const f=x=>523.25*Math.pow(2,x/12);
 if(k==="ok"){const b=f(SEMI[Math.min(n,8)]);tone(b,0,.18,"triangle");tone(b*1.5,.09,.3,"triangle")}
 else if(k==="bad"){tone(200,0,.22,"sawtooth",.09);tone(150,.16,.35,"sawtooth",.09)}
 else if(k==="mile"){[0,4,7,12,16].forEach((s,i)=>tone(f(s),i*.08,.35,"triangle",.15));tone(f(19),.4,.6,"sine",.14)}
 else if(k==="fin"){if(n>=90){[0,4,7,12].forEach((s,i)=>tone(f(s),i*.13,.3,"square",.08));[0,4,7,12,16].forEach(s=>tone(f(s),.6,1.1,"triangle",.1));tone(f(19),.7,1.2,"sine",.12)}else if(n>=60){[0,4,7,12].forEach((s,i)=>tone(f(s),i*.12,.4,"triangle",.14))}else{tone(f(0),0,.3,"triangle",.14);tone(f(7),.15,.5,"triangle",.14)}}
 else if(k==="on"){tone(f(7),0,.15,"triangle")}}
function mute(){S.snd=snd()?0:1;save();document.querySelectorAll(".mu").forEach(e=>e.textContent=snd()?"🔊":"🔇");sfx("on")}
const muBtn=c=>`<span class="mu ${c||""}" role="button" tabindex="0" aria-label="Sound on or off" onclick="mute()">${snd()?"🔊":"🔇"}</span>`;
const MS={3:["On a roll","🔥"],5:["Blazing!","🔥"],10:["Unstoppable!","🚀"],15:["Legendary!","👑"],20:["Absolute legend","🏆"]};
function milestone(n){const m=MS[n];if(!m)return;sfx("mile");try{if(reduced())return;const d=document.createElement("div");d.className="mile m"+(n>=15?3:n>=10?2:n>=5?1:0);d.innerHTML=`<div class="mf">${m[1]}</div><div class="mt">${n} in a row</div><div class="ms">${m[0]}</div>`;document.body.appendChild(d);setTimeout(()=>d.remove(),2300)}catch(e){}}
function xpBig(){try{const x2=/~x$/.test(typeof cid!=="undefined"&&cid||""),d=document.createElement("div");d.className="xpbig"+(x2?" x2b":"");d.textContent=x2?"+20 XP ⚡":"+10 XP";document.body.appendChild(d);setTimeout(()=>d.remove(),2200)}catch(e){}}
const stk=()=>streak>=2?`<span class="stk t${streak>=15?4:streak>=10?3:streak>=5?2:1}">🔥 ${streak}</span>`:"";
function stars(){let s="";for(let i=0;i<12;i++)s+=`<b style="--a:${i*30}deg">${i%2?"✨":"⭐"}</b>`;return s}
function celebrate(msg){try{sfx("mile");confetti(30)}catch(e){}try{toast(msg)}catch(e){}}
function bump(){try{const x=document.querySelector(".xp");x.classList.remove("bump");void x.offsetWidth;x.classList.add("bump")}catch(e){}}
function countUp(id,to,suf){const el=document.getElementById(id);if(!el)return;if(typeof requestAnimationFrame!=="function"||reduced()){el.textContent=to+suf;return}el.textContent="0"+suf;const t0=performance.now();const step=t=>{const p=Math.min(1,(t-t0)/700);el.textContent=Math.round(to*(1-Math.pow(1-p,3)))+suf;if(p<1)requestAnimationFrame(step)};requestAnimationFrame(step)}
