const QR_D=[["C2","Back of the head"],["C3","Neck and the hollow above the collarbone"],["C4","Top of the shoulder"],["C5","Lateral upper arm, from the deltoid to the elbow"],["C6","Thumb and lateral forearm"],["C7","Middle finger"],["C8","Little finger and medial hand"],["T1","Medial forearm and inner elbow"],["T2","Axilla and medial upper arm"],["T3","Upper chest, just above the nipple line"],["T4","Nipple line"],["T5","Just below the nipple line"],["T6","Xiphoid process"],["T7 to T9","Upper abdomen, between the xiphoid and the umbilicus"],["T10","Umbilicus"],["T11","Between the umbilicus and the inguinal ligament"],["T12","Just above the inguinal ligament"],["L1","Groin and upper anterior thigh"],["L2","Anterior mid thigh"],["L3","Lower anterior thigh and medial knee"],["L4","Medial lower leg and medial malleolus"],["L5","Lateral lower leg, dorsum of foot and great toe"],["S1","Lateral foot and heel"],["S2","Posterior thigh and calf, midline"],["S3 to S5","Saddle area: perineum and around the anus"]];
const QR_M=[["C1 to C2","Neck flexion"],["C3","Neck lateral flexion"],["C4","Shoulder elevation (shrug)"],["C5","Shoulder abduction"],["C6","Elbow flexion and wrist extension"],["C7","Elbow extension and wrist flexion"],["C8","Thumb extension and finger flexion"],["T1","Finger abduction"],["L1 to L2","Hip flexion"],["L3","Knee extension"],["L4","Ankle dorsiflexion"],["L5","Great toe extension"],["S1","Ankle plantarflexion and eversion"],["S2","Knee flexion"]];
const QR_R=[["Biceps","C5 to C6"],["Brachioradialis","C5 to C6 (some sources stress C6)"],["Triceps","C7"],["Knee (patellar)","L3 to L4"],["Ankle (Achilles)","S1"]];
const QR_B=[["Full blood count",[["Haemoglobin (Hb)","Men 130 to 170 g/L · women 120 to 150 g/L","Low: dizziness, fatigue, breathlessness on exertion"],["White cell count (WCC)","4.0 to 11.0 ×10⁹/L","High: infection or inflammation. Low: infection risk"],["Neutrophils","2.0 to 7.5 ×10⁹/L","Low (neutropenia): check infection control precautions"],["Platelets","150 to 400 ×10⁹/L","Low: bleeding and bruising risk if they fall"]]],
["Kidneys and electrolytes",[["Sodium (Na⁺)","135 to 145 mmol/L","Low or high: confusion, falls, seizures"],["Potassium (K⁺)","3.5 to 5.3 mmol/L","Low or high: heart rhythm problems"],["Urea","2.5 to 7.8 mmol/L","High: dehydration or kidney problems"],["Creatinine","Men about 60 to 110 · women about 45 to 90 µmol/L","High: reduced kidney function"],["eGFR","Above 90 mL/min/1.73m²","Falling: worsening kidney function"],["Magnesium","0.7 to 1.0 mmol/L","Low: cramps, weakness, arrhythmia"],["Calcium (adjusted)","2.2 to 2.6 mmol/L","Abnormal: weakness, confusion, arrhythmia"]]],
["Clotting",[["INR","0.8 to 1.2 (on warfarin, usually 2 to 3)","High: bleeding risk"],["D-dimer","Below the lab cut-off","Raised is non-specific. A normal result helps rule out a clot"]]],
["Other",[["CRP","Below 5 mg/L","Rising: infection or inflammation. Watch the trend"],["Troponin","Below the lab cut-off","Raised: possible heart muscle damage. Check the medical plan"],["Lactate","Below 2 mmol/L","High: poor tissue perfusion, possible sepsis"],["Glucose","4 to 7 mmol/L before meals (common target)","Low: risk of collapse. High: check diabetes plan"],["Albumin","35 to 50 g/L","Low: poor nutrition or illness, slower healing"]]]];
let qrT="derm",qrSel=null;
setTimeout(()=>{try{S.lsSig=S.lsSig||{};let ch=0;TPL_RG.forEach(r=>(RGL[r]||{ls:[]}).ls.forEach(id=>{const sig=JSON.stringify(lsBounds(id));if(S.lsSig[id]!==sig){if(S.lsSig[id]!==undefined||!S.lsN2){if(S.les){delete S.les["P:"+id];delete S.les["M:"+id];delete S.les["Q:"+id]}}S.lsSig[id]=sig;ch=1}}));if(!S.lsN2){S.lsN2=1;ch=1}if(ch)save()}catch(e){}try{if(S&&!S.lsN1){Object.values(RGL).forEach(r=>r.ls.forEach(id=>{if(lsN(id)!==3&&S.les){delete S.les["P:"+id];delete S.les["M:"+id];delete S.les["Q:"+id]}}));S.lsN1=1;save()}}catch(e){}},0);
function qrOpen(t){qrT=t||qrT;qrSel=null;infoSheet(`<div id="qrw">${qrBody()}</div>`,"Quick reference")}
function qrTab(t){qrT=t;qrSel=null;const w=document.getElementById("qrw");if(w){w.innerHTML=qrBody();hap("tap")}}
function qrPick(k,fig){qrSel=qrSel===k?null:k;if(qrSel==="C2"||qrSel==="S2"||qrSel==="S3 to S5")qrDv="b";const w=document.getElementById("qrw");if(w)w.innerHTML=qrBody();if(fig)return;const r=document.querySelector(qrT==="derm"&&qrSel?".dzseg":".qrrow.on");if(r)r.scrollIntoView({block:"nearest",behavior:"smooth"})}
function qrGo(rg){document.querySelectorAll(".ifbg").forEach(e=>e.remove());tab="found";curPack=null;openRegion(rg)}
let qrDv="f";
