function qrFig(){const d=QR_D.find(x=>x[0]===qrSel);
 return `<div class="dzseg" role="tablist" aria-label="Side of the body"><button role="tab" aria-selected="${qrDv==="f"}" class="${qrDv==="f"?"on":""}" onclick="qrSide('f')">Front</button><button role="tab" aria-selected="${qrDv==="b"}" class="${qrDv==="b"?"on":""}" onclick="qrSide('b')">Back</button></div>`+
  `<p class="dzcap" aria-live="polite">${d?`<b>${d[0]}</b>${esc(d[1])}`:"Tap an area to see its level."}</p>`+(window.dzSvg?dzSvg(qrDv,qrSel):"")+
  `<div class="dzkey" aria-hidden="true"><span><i class="c"></i>Cervical</span><span><i class="t"></i>Thoracic</span><span><i class="l"></i>Lumbar</span><span><i class="s"></i>Sacral</span><span><i class="k"></i>Test point</span></div>`}
const QR_ROM=[
 ["Shoulder","",[["Flexion","about 180°"],["Extension","about 60°"],["Abduction","about 180°"],["External rotation","about 90° (arm abducted to 90°)"],["Internal rotation","about 70° (arm abducted to 90°)"],["Horizontal adduction","about 135° (from 90° abduction)"],["Horizontal abduction","about 45° (from 90° abduction)"]]],
 ["Elbow and forearm","Forearm rotation is measured with the elbow at 90° and tucked into the side, so the shoulder can't help.",[["Flexion","about 145°"],["Extension","0° (up to about 10° beyond straight can be normal)"],["Supination","about 80° to 90°"],["Pronation","about 80°"]]],
 ["Wrist","",[["Flexion","about 80°"],["Extension","about 70°"],["Radial deviation","about 20°"],["Ulnar deviation","about 30°"]]],
 ["Fingers and thumb","",[["Finger MCP flexion","about 90°"],["Finger MCP extension","about 30° beyond straight"],["Finger PIP flexion","about 100°"],["Finger DIP flexion","about 80°"],["Thumb MCP flexion","about 50°"],["Thumb IP flexion","about 80°"]]],
 ["Hip","Flexion is measured with the knee bent. Rotation is measured with the hip and knee at 90° (sitting) or lying prone with the knee bent, so say which.",[["Flexion","about 120°"],["Extension","about 10° to 20°"],["Abduction","about 40° to 45°"],["Adduction","about 25° to 30°"],["External rotation","about 45°"],["Internal rotation","about 35° to 45°"]]],
 ["Knee","",[["Flexion","about 135°"],["Extension","0° (up to about 10° beyond straight can be normal)"]]],
 ["Ankle and foot","Dorsiflexion is less with the knee straight than bent, because gastrocnemius crosses the knee. Record which you used.",[["Dorsiflexion","about 10° to 20°"],["Plantarflexion","about 50°"],["Inversion","about 35° (subtalar and midfoot together)"],["Eversion","about 15° (subtalar and midfoot together)"],["Big toe extension (1st MTP)","about 70°"]]],
 ["Cervical spine","Sources vary widely here and range falls noticeably with age. Ask about dizziness or arm symptoms as you go.",[["Flexion","about 50° (chin close to the chest)"],["Extension","about 60° to 70°"],["Side flexion","about 45°"],["Rotation","about 70° to 80°"]]],
 ["Lumbar spine","Often recorded as a distance or a description rather than in degrees. Note where any pain or stiffness comes on.",[["Flexion","fingertips to about mid-shin or lower. Modified Schober: an increase of about 5 cm or more is typical"],["Extension","about 20° to 30°"],["Side flexion","about 20° to 30° (fingertips slide to about knee level)"],["Rotation","small in the lumbar spine. Most trunk rotation comes from the thoracic spine"]]]];
function qrBody(){const T=[["derm","Dermatomes"],["myo","Myotomes"],["refl","Reflexes"],["tone","Tone"],["rom","ROM"],["ews","EWS"],["bl","Bloods"],["sc","Scales"],["lad","Resp ladders"],["med","Medicines"]];
 let o=`<h2 style="margin:6px 0 10px;font-size:1.25rem">📌 Quick reference</h2><div class="qrtabs" role="tablist">${T.map(t=>`<button role="tab" aria-selected="${qrT===t[0]}" class="${qrT===t[0]?"on":""}" onclick="qrTab('${t[0]}')">${t[1]}</button>`).join("")}</div>`;
 const row=(a,b,cls)=>`<div class="qrrow${cls||""}"><b>${a}</b><span>${b}</span></div>`;
 if(qrT==="derm"){o+=`<p class="qrnote">Tap an area or a row to find a level. Dots mark the standard points for testing light touch and pinprick.</p>${qrFig()}<div class="qrlist">${QR_D.map(d=>`<div class="qrrow${qrSel===d[0]?" on":""}" onclick="qrPick('${d[0]}')"><b>${d[0]}</b><span>${esc(d[1])}</span></div>`).join("")}</div>
 <div class="qrwarn">🚨 Saddle numbness (S3 to S5) with new bladder or bowel change: suspected cauda equina. Escalate urgently.</div>
 <p class="qrnote">A simplified map in the pattern used with the ISNCSCI key sensory points. Maps differ between sources and neighbouring dermatomes overlap. Compare sides and combine with myotomes and reflexes.</p>`}
 if(qrT==="myo")o+=`<p class="qrnote">Hold each resisted movement briefly and compare sides.</p><div class="qrlist">${QR_M.map(m=>row(m[0],m[1])).join("")}</div><p class="qrnote">Textbooks vary by a level. Most muscles have more than one root, so weakness in one myotome is a clue, not a diagnosis.</p>`;
 if(qrT==="refl")o+=`<div class="qrlist qrwide">${QR_R.map(r=>row(r[0],r[1])).join("")}</div><h3>Grading</h3><div class="qrlist">${[["0","Absent"],["1+","Reduced"],["2+","Normal"],["3+","Brisk"],["4+","Very brisk, often with clonus"]].map(g=>row(g[0],g[1])).join("")}</div>
 <p class="qrnote"><b>Reduced</b> reflexes suggest a lower motor neurone problem (root or nerve). <b>Brisk</b> reflexes suggest an upper motor neurone problem.</p><div class="qrwarn">🚨 Brisk reflexes with Hoffmann's sign, an upgoing plantar response, clonus or new gait change: think spinal cord involvement and escalate per local policy.</div>`;
 if(qrT==="tone")o+=`<h3>Types of abnormal tone</h3><div class="qrlist">${[["Hypotonia","Reduced resistance, floppy or flaccid limb. Seen in lower motor neurone and cerebellar problems, and early after a stroke or spinal cord injury."],["Spasticity","Resistance that increases with the speed of the stretch, sometimes with a clasp-knife release. An upper motor neurone sign (stroke, MS, spinal cord injury, cerebral palsy)."],["Rigidity","Resistance throughout the range whatever the speed: lead-pipe (even) or cogwheel (ratchety). Typical of Parkinson's."],["Dystonia","Involuntary sustained or twisting contractions that change with posture, effort or emotion."],["Clonus","Rhythmic beats when a muscle is stretched quickly. A few beats can be normal; sustained clonus suggests an upper motor neurone problem."]].map(g=>row(g[0],g[1])).join("")}</div>
 <h3>Modified Ashworth Scale (spasticity)</h3><div class="qrlist">${[["0","No increase in tone"],["1","Slight increase: a catch and release, or minimal resistance at the end of range"],["1+","Slight increase: a catch, then minimal resistance through the rest (less than half) of the range"],["2","More marked increase through most of the range, but the limb is still easily moved"],["3","Considerable increase: passive movement is difficult"],["4","Limb rigid in flexion or extension"]].map(g=>row(g[0],g[1])).join("")}</div>
 <p class="qrnote"><b>Tardieu Scale:</b> compares a slow stretch with a fast stretch. The angle where you feel the catch on the fast stretch (R1) and the full passive range on the slow stretch (R2) show how much of the stiffness is speed-dependent.</p>
 <p class="qrnote">Test with the patient relaxed and supported, move slowly then quickly, and compare sides. Pain, position, temperature and time of day all change tone, so note them and keep them the same when you retest.</p>`;
 if(qrT==="ews")o+=`<p class="qrnote" style="opacity:1">Early warning scores: NEWS2 for adults, PEWS for children.</p><h3>NEWS2 (adults)</h3><p class="qrnote">Score each parameter and add them up.</p><div class="qrlist qrwide">${[["Breathing rate","0: 12 to 20 · 1: 9 to 11 · 2: 21 to 24 · 3: 8 or less, or 25 or more"],["SpO₂ scale 1","0: 96% or more · 1: 94 to 95 · 2: 92 to 93 · 3: 91 or less"],["SpO₂ scale 2","Only when a clinician has documented it: confirmed hypercapnic respiratory failure, target 88 to 92% · 0: 88 to 92, or 93+ on air · 1: 86 to 87, or 93 to 94 on oxygen · 2: 84 to 85, or 95 to 96 on oxygen · 3: 83 or less, or 97+ on oxygen"],["Air or oxygen","0: air · 2: any supplemental oxygen"],["Systolic BP","0: 111 to 219 · 1: 101 to 110 · 2: 91 to 100 · 3: 90 or less, or 220 or more"],["Pulse","0: 51 to 90 · 1: 41 to 50, or 91 to 110 · 2: 111 to 130 · 3: 40 or less, or 131 or more"],["Consciousness","0: alert · 3: new confusion, or responds only to voice or pain, or unresponsive"],["Temperature","0: 36.1 to 38.0 · 1: 35.1 to 36.0, or 38.1 to 39.0 · 2: 39.1 or more · 3: 35.0 or less"]].map(g=>row(g[0],g[1].replace(/ · /g,"<br>"))).join("")}</div>
 <h3>NEWS2 response</h3><div class="qrlist qrwide">${[["0 to 4","Low: ward-based response"],["3 in one parameter","Low to medium: urgent ward-based response"],["5 to 6","Medium: urgent review by a clinician skilled in acute illness"],["7 or more","High: emergency response, often critical care outreach"]].map(g=>row(g[0],g[1])).join("")}</div><p class="qrnote" style="opacity:1"><b>5 or more with a known or likely infection: think sepsis.</b> NEWS2 isn't for under-16s or in pregnancy, and can be unreliable after a spinal cord injury. Follow your local escalation policy.</p>
 <h3>PEWS (children)</h3><p class="qrnote" style="opacity:1">In England, the national Paediatric Early Warning System (PEWS) uses <b>four age-specific charts</b>, because normal observations change a lot as children grow. Other UK nations and some trusts use their own versions.</p><div class="qrlist qrwide">${[["0 to 11 months","Infant chart"],["1 to 4 years","Toddler and pre-school chart"],["5 to 12 years","School-age chart"],["13 years and over","Young person chart"]].map(g=>row(g[0],g[1])).join("")}</div>
 <p class="qrnote">It scores breathing rate, breathing effort, oxygen saturation, oxygen needs, heart rate, systolic blood pressure and capillary refill time in colour-coded bands, and escalation rises with the score. Temperature and alertness are charted but not scored, and a change in alertness is a trigger to escalate. The scoring bands are on each chart, so always use your trust's chart for the child's age.</p>
 <div class="qrwarn">🚨 If a parent or carer says their child is getting worse, escalate, whatever the score. Parents know what is normal for their child.</div>
 <h3>Typical normal ranges in children</h3><div class="qrlist qrwide">${[["Under 1 year","Breathing 30 to 40 · heart rate 110 to 160 · systolic BP 70 to 90"],["1 to 2 years","Breathing 25 to 35 · heart rate 100 to 150 · systolic BP 85 to 95"],["2 to 5 years","Breathing 25 to 30 · heart rate 95 to 140 · systolic BP 85 to 100"],["5 to 12 years","Breathing 20 to 25 · heart rate 80 to 120 · systolic BP 90 to 110"],["Over 12 years","Breathing 15 to 20 · heart rate 60 to 100 · systolic BP 100 to 120"]].map(g=>row(g[0],g[1].replace(/ · /g,"<br>"))).join("")}</div>
 <p class="qrnote">Approximate awake values, as taught on APLS courses. Sources vary a little, and fever, crying and pain all raise them. Look at the trend and how the child looks.</p>`;
 if(qrT==="rom")o+=`<p class="qrnote">Typical adult active range. Values vary by 10° to 20° between sources and people and fall with age, so compare with the other side and record the starting position.</p>${QR_ROM.map((j,i)=>`<h3>${esc(j[0])}</h3>${j[1]?`<p class="qrnote">${esc(j[1])}</p>`:""}<div class="qrlist qrwide">${j[2].map(g=>row(esc(g[0]),esc(g[1]))).join("")}</div>${i===0?`<div class="qrgo"><button class="chipb" onclick="qrGo('shoulder')">Practise: Shoulder joints ›</button></div>`:""}`).join("")}`;
 if(qrT==="bl")o+=`<p class="qrnote">Typical adult ranges. Use the ranges on your lab's report, as they vary between labs.</p>${QR_B.map(g=>`<h3>${g[0]}</h3><div class="qrlist qrwide">${g[1].map(r=>`<div class="qrrow"><b>${r[0]}</b><span>${r[1]}<small>${r[2]}</small></span></div>`).join("")}</div>`).join("")}<p class="qrnote">Safe ranges for exercise and mobilising vary between trusts. Look at the trend and how the patient is, and check your local policy or ask the medical team if you are unsure.</p>`;
 if(qrT==="med")o+=window.QRMED?QRMED():"";
 if(qrT==="lad")o+=`<p class="qrnote">Start at the bottom of the ladder for the main problem and reassess after each step. Ladders vary between trusts; follow local policy.</p>${window.RLAD?RLAD.vol+RLAD.sput+RLAD.wob:""}`;
 if(qrT==="sc")o+=`<h3>Muscle strength (Oxford or MRC scale)</h3><div class="qrlist">${[["0","No contraction"],["1","Flicker of contraction"],["2","Movement with gravity eliminated"],["3","Full range against gravity"],["4","Against some resistance"],["5","Normal power"]].map(g=>row(g[0],g[1])).join("")}</div>
 <h3>Adding + or −</h3><p class="qrnote" style="opacity:1">A + or − adds detail within a grade. There are two common versions: one based on <b>resistance</b> (for grade 4) and one based on <b>range of movement</b> (for grades 2 and 3).</p><h3 style="font-size:.95rem">Resistance version</h3><div class="qrlist">${[["4−","Against slight resistance"],["4","Against moderate resistance"],["4+","Against strong resistance, but not normal"]].map(g=>row(g[0],g[1])).join("")}</div>
 <h3 style="font-size:.95rem">Range of movement version</h3><div class="qrlist">${[["2−","Partial range with gravity eliminated"],["2","Full range with gravity eliminated"],["2+","Full range with gravity eliminated, and starts to move against gravity"],["3−","More than half, but not full, range against gravity"],["3","Full range against gravity"],["3+","Full range against gravity, and holds against slight resistance"]].map(g=>row(g[0],g[1])).join("")}</div>
 <p class="qrnote">Definitions vary between sources and teams. Say which version you use in your notes, test both sides, and keep the same tester and position when you retest.</p>
 <h3>Sputum (secretions)</h3><div class="qrlist qrwide">${[["M1","Mucoid, no pus"],["M2","Mostly mucoid, some suspicion of pus"],["P1","About one third purulent"],["P2","One to two thirds purulent"],["P3","More than two thirds purulent"]].map(g=>row(g[0],g[1])).join("")}</div><p class="qrnote">Miller classification. Also record consistency (thin, thick, tenacious), volume (small, moderate, copious, or mL; 24-hour pot volume in bronchiectasis) and any blood. A change from the patient's usual matters most.</p>
 <h3>ABG normal values</h3><div class="qrlist">${[["pH","7.35 to 7.45"],["PaCO₂","4.7 to 6.0 kPa"],["PaO₂","Above 10 kPa on air"],["HCO₃⁻","22 to 26 mmol/L"],["Base excess","−2 to +2"]].map(g=>row(g[0],g[1])).join("")}</div>
 <p class="qrnote">Ranges vary slightly by lab, and escalation follows your trust's policy.</p>`;
 const L=qrT==="derm"?[["neck","Neck dermatomes"],["thor","Thoracic dermatomes"]]:qrT==="myo"?[["neck","Neck myotomes"],["elbow","Elbow and hand"]]:qrT==="refl"?[["found","Reflexes in Foundations"],["neck","Neck reflexes"]]:[];
 if(L.length)o+=`<div class="qrgo">${L.map(l=>`<button class="chipb" onclick="qrGo('${l[0]}')">Practise: ${l[1]} ›</button>`).join(" ")}</div>`;
 if(qrT==="derm"||qrT==="myo"||qrT==="refl")o+=`<p class="qrnote">Lower limb levels are a reference only for now. They will be taught when the lumbar region is added.</p>`;
 return o}
/* ---------- Streak countdown (in-app stand-in for the home screen widget) ---------- */
function stkLeft(){const n=new Date(),m=new Date(n);m.setHours(24,0,0,0);return m-n}
function stkDoneToday(){return S.last===new Date().toDateString()}
function stkFmt(ms){const h=Math.floor(ms/36e5),m=Math.floor(ms%36e5/6e4);return h?`${h}h ${m}m`:`${m}m`}
function stkLvl(ms){return ms>8*36e5?0:ms>3*36e5?1:ms>36e5?2:3}
function stkCD(where){const st=S.streak||0;if(!st||stkDoneToday())return "";const y=new Date(Date.now()-864e5).toDateString();if(S.last!==y)return "";
 const ms=stkLeft(),lv=stkLvl(ms),al=S.al||0,msg=["Plenty of time today.","Fit a segment in this evening.","A 2-minute segment is all it takes.","Last call: it ends at midnight."][lv];
 return `<button class="skcd l${lv}" onclick="${where==="path"?"pathJump()":"(document.querySelector('.nx')||{click(){}}).click()"}" aria-label="${stkFmt(ms)} left to keep your ${st}-day streak">
 <span class="skv">${mascot(46,lv<2?"cheer":"")}${lv>=2?`<i class="skdrop">💧</i>`:""}${lv===3?`<i class="skdrop d2">💧</i>`:""}</span>
 <span class="skt"><b><span id="skcdt">${stkFmt(ms)}</span> left</b><small>to keep your 🔥 ${st}-day streak. ${msg}${al&&lv===3?` 🏖️ Annual leave will cover you if not.`:""}</small></span></button>`}
setInterval(()=>{try{const e=document.getElementById("skcdt");if(!e)return;if(stkDoneToday()){const b=e.closest(".skcd");if(b)b.remove();return}const ms=stkLeft(),b=e.closest(".skcd");e.textContent=stkFmt(ms);if(b){const l=stkLvl(ms);if(!b.classList.contains("l"+l)){b.className="skcd l"+l}}}catch(x){}},30000);

