 let cerv="",lum="";for(let i=0;i<5;i++){cerv+=`<rect x="114" y="${66+i*6.5}" width="12" height="6" rx="2.5" fill="var(--bone)" stroke="var(--mute)" stroke-width="2"/>`;lum+=`<rect x="${107-i*.5}" y="${192+i*15}" width="${26+i}" height="12" rx="4" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.2"/>`}
 const arm=bn("M118 98Q96 92 76 100",7)+`<circle cx="70" cy="106" r="9" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.5"/>`+bn("M68 114L56 186",9)+`<circle cx="54" cy="190" r="6" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.2"/>`+bn("M52 197L41 262",6)+bn("M58 196L51 262",5)+sh("M32 266Q41 262 51 266L53 288Q42 294 33 288Z")+bn("M35 291L33 306M40 293L40 311M46 293L46 309M51 291L53 304",3.5);
 const leg=sh("M118 244C98 226 70 224 60 242C54 262 70 286 94 292L110 276L118 272Z")+`<circle cx="86" cy="286" r="9" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.5"/>`+bn("M84 296Q88 340 92 388",12)+`<ellipse cx="92" cy="397" rx="7" ry="8" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.2"/>`+bn("M94 410L98 478",9)+bn("M105 410L107 476",5)+sh("M88 482Q100 476 112 482L118 500Q100 506 84 502Z")+bn("M86 504L86 508M92 505L92 509M98 505L98 509M104 504L104 508",3);
 const mid=`<ellipse cx="120" cy="36" rx="21" ry="24" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.5"/><path d="M105 52Q108 68 120 68Q132 68 135 52Z" fill="var(--bone)" stroke="var(--mute)" stroke-width="2.5" stroke-linejoin="round"/><circle cx="111" cy="40" r="5" fill="var(--bg)"/><circle cx="129" cy="40" r="5" fill="var(--bg)"/><path d="M120 46L117 54H123Z" fill="var(--bg)"/>`+cerv+sh("M114 100H126V152Q126 156 120 156Q114 156 114 152Z")+lum+sh("M104 252H136L120 294Z");
 let ov="";
 if(sel==="s-neuro")ov=`<g class="ov">${[["#A87800",6],["#FFD23F",3.4]].map(c=>`<g fill="none" stroke="${c[0]}" stroke-width="${c[1]}" stroke-linecap="round" stroke-linejoin="round"><path d="M120 66V292"/>${two(`<path d="M119 98Q92 96 72 108L56 188L42 268"/><path d="M114 292Q98 330 94 392L98 478"/>`)}</g>`).join("")}<path d="M101 33C99 20 108 13 120 13C132 13 141 20 139 33C140 40 133 42 120 42C107 42 100 40 101 33Z" fill="#FFD23F" stroke="#A87800" stroke-width="2.5" stroke-linejoin="round"/><path d="M120 14V41M108 22Q112 28 108 34M132 22Q128 28 132 34" fill="none" stroke="#A87800" stroke-width="2" stroke-linecap="round"/><circle cx="111" cy="40" r="5" fill="var(--bg)"/><circle cx="129" cy="40" r="5" fill="var(--bg)"/></g>`;
 if(sel==="s-resp")ov=`<g class="ov" stroke="#6A35D9" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"><path d="M120 70V112M120 112L104 128M120 112L136 128" fill="none"/>${two(`<path d="M114 114Q84 116 80 160Q82 192 110 188Z" fill="#8A4DFF" fill-opacity=".7"/><path d="M104 130L96 150M102 140L92 160" fill="none" stroke="#C9B3FF" stroke-width="2"/>`)}</g>`;
 if(sel==="s-cv")ov=`<g class="ov"><path transform="translate(-44 -49) scale(1.35)" d="M124 150C110 138 112 124 122 126C126 128 126 130 126 132C128 126 140 124 140 136C140 146 130 152 124 158Z" fill="#E5383B" stroke="#B3201F" stroke-width="2" stroke-linejoin="round"/><g fill="none" stroke="#E5383B" stroke-width="3" stroke-linecap="round"><path d="M126 126V104M120 160V292M100 292Q90 340 94 392M140 292Q150 340 146 392"/></g></g>`;
 const hs=(id,sh2,mir)=>`<g class="hs${sel===id?" on":""}${RG.some(r=>r.id===id&&r.live)?" live":""}" role="button" tabindex="0" aria-label="${(ALLR.find(r=>r.id===id)||{}).n}" onclick="selBody('${id}')" onkeydown="if(event.key==='Enter')selBody('${id}')">${mir?two(sh2):sh2}</g>`;
 const z=t=>t.replace(/<(circle|ellipse|rect)/g,'<$1 class="hz"');
 const spots=hs("thor",z(`<ellipse cx="120" cy="146" rx="34" ry="44"/>`))+hs("lumb",z(`<ellipse cx="120" cy="250" rx="52" ry="42"/>`))+hs("neck",z(`<rect x="102" y="62" width="36" height="38" rx="12"/>`))+hs("shoulder",z(`<circle cx="72" cy="106" r="20"/>`),1)+hs("elbow",z(`<circle cx="54" cy="190" r="14"/>`),1)+hs("wrist",z(`<ellipse cx="42" cy="285" rx="16" ry="26"/>`),1)+hs("hip",z(`<circle cx="86" cy="286" r="16"/>`),1)+hs("knee",z(`<circle cx="92" cy="396" r="17"/>`),1)+hs("ankle",z(`<ellipse cx="100" cy="490" rx="22" ry="20"/>`),1);
 return `<svg class="skel" viewBox="0 0 240 516" role="group" aria-label="Skeleton body map. Tap a region to choose it.">${two(arm)}${two(leg)}${ribs.replace(/^/,"")}<g transform="translate(240 0) scale(-1 1)">${ribs}</g>${mid}${ov}${spots}</svg>`;
