 const M=new Map();COND.forEach(c=>(c.gl||[]).forEach(g=>{const key=g.u||(g.t+"|"+g.s);const e=M.get(key)||{g,conds:[],areas:new Set(),chk:c.chk};e.conds.push(c);e.areas.add(c.tags[0]);if(c.chk>e.chk)e.chk=c.chk;M.set(key,e)}));
 const all=[...M.values()];const q=glQ.trim().toLowerCase();
 const hit=e=>(!glT||kOf(e.g)===glT)&&(!q||(e.g.t+" "+e.g.s+" "+e.g.n+" "+e.conds.map(c=>c.n).join(" ")).toLowerCase().includes(q));
 const row=e=>`<div class="glr"><b>${esc(e.g.t)}</b>${window.glTag?glTag(e.g):""}<small>${esc(e.g.s)} · checked ${esc(e.chk)}</small><span>${esc(e.g.n)}</span><div class="glu">Used in: ${e.conds.map(c=>`<button class="lnk" onclick="openCond('${c.id}')">${esc(c.n)}</button>`).join(", ")}</div>${e.g.u?`<a href="${esc(e.g.u)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:`<em>Link to confirm</em>`}</div>`;
