 const NS="http://www.w3.org/2000/svg",svg=document.createElementNS(NS,"svg");svg.setAttribute("class","spine");svg.setAttribute("aria-hidden","true");svg.setAttribute("viewBox","0 0 "+pr.width+" "+pr.height);svg.setAttribute("width",pr.width);svg.setAttribute("height",pr.height);
