function kitAchSync(){S.kitAch=S.kitAch||{};let nw=[];Object.keys(ACH).forEach(a=>{if(!S.kitAch[a]){let ok=false;try{ok=ACH[a].ok()}catch(e){}if(ok){S.kitAch[a]=1;nw.push(a)}}});return nw}
