/* streak protection */
function alApply(){try{if(!S.last)return;const t=new Date();t.setHours(12,0,0,0);const l=new Date(S.last);l.setHours(12,0,0,0);const gap=Math.round((t-l)/864e5)-1;if(gap<1)return;const al=S.al||0;if(gap<=al&&(S.streak||0)>0){S.al=al-gap;const y=new Date(Date.now()-864e5).toDateString();S.last=y;S.alUsed=(S.alUsed||[]).concat([isoD(new Date())]).slice(-20);try{S.df=S.df||{};for(let k=1;k<=gap;k++)S.df[isoD(new Date(Date.now()-k*864e5))]=1}catch(e){}save();setTimeout(()=>toast("🏖️ "+gap+" annual leave day"+(gap>1?"s":"")+" used. Your streak is safe."),900)}}catch(e){}}
function alEarn(){const e=Math.floor((S.xpT||0)/500);if(S.alE==null){S.alE=e;return 0}if(e>S.alE){const add=Math.min(e-S.alE,3-(S.al||0));S.alE=e;if(add>0){S.al=(S.al||0)+add;return add}}return 0}
