function goPath(){try{const f=document.getElementById("fb");if(f)f.remove();if(stkPending())app.innerHTML=""}catch(e){}celebNext(home)}
function lvCheck(){try{if(document.getElementById("fb")||document.querySelector(".cpc,.lvc,.achov,.stkov")||LES||(typeof queue!=="undefined"&&queue.length))return false;const n=lvOf(S.xpT),was=S.lvSeen||0;if(S.bestStreak==null||(S.streak||0)>S.bestStreak)S.bestStreak=Math.max(S.bestStreak||0,S.streak||0);
 const na=kitAchSync(),al=alEarn();if(!was){S.lvSeen=n;save();return false}
 if(n>was){S.lvSeen=n;save();try{fdPost("🎉","Reached level "+n+": "+LVL[n-1][1],"lv:"+n)}catch(er){}lvShow(n,KIT.filter(k=>k.lv&&k.lv>was&&k.lv<=n),al);return true}else if(na.length){save();lvShow(0,KIT.filter(k=>na.includes(k.ach)),al);return true}else if(al){save();toast("🏖️ Annual leave day earned")}else save()}catch(e){}LVNEXT=null;return false}
function lvShow(n,items,al){const o=document.createElement("div");o.className="cpc lvc";o.setAttribute("role","dialog");const L=LVL[n-1];
 const prev=Object.assign({},S.kit||{});items.forEach(k=>prev[k.s]=k.id);
 o.innerHTML=`<div class="cpcin"><div class="cpcv">${mascot(130,"cheer",prev)}</div>${n?`<p class="tag" style="text-align:center;margin:0">Level up</p><h1>Level ${n}</h1><p class="cpcm" style="font-weight:800;font-size:1.15rem">${esc(L[1])}</p>`:`<p class="tag" style="text-align:center;margin:0">Kit unlocked</p><h1>${esc(items.map(k=>k.n).join(" and "))}</h1><p class="cpcm">${esc(items.map(k=>ACH[k.ach]?ACH[k.ach].d:"").filter(Boolean).join(". "))}. Nice work.</p>`}`+
 (items.length?`<div class="cpcp">${items.map(k=>`<span>🎒 ${esc(k.n)}</span>`).join("")}</div>`:"")+(al?`<p class="tag" style="text-align:center;margin-top:10px">🏖️ Plus ${al} annual leave day${al>1?"s":""} to protect your streak.</p>`:"")+
 `${items.length?`<button class="go" onclick="S.kit=Object.assign(S.kit||{},${esc(JSON.stringify(Object.fromEntries(items.map(k=>[k.s,k.id]))))});save();LVNEXT=LVNEXT||home;lvDone(this)">Put it on</button><button class="opt" style="text-align:center;margin-top:8px" onclick="lvDone(this)">Maybe later</button>`:`<button class="go" onclick="lvDone(this)">Continue</button>`}</div>`;
 document.body.appendChild(o);confetti(50);setTimeout(()=>confetti(40),700);try{sfx("fin",100);hap("mile")}catch(e){}}
