function pfGeo(S0){const im=pc.img,b=Math.max(S0/im.naturalWidth,S0/im.naturalHeight)*pc.z,w=im.naturalWidth*b,h=im.naturalHeight*b,mx=Math.max(0,(w-S0)/2),my=Math.max(0,(h-S0)/2);pc.x=Math.max(-mx*560/S0,Math.min(mx*560/S0,pc.x));pc.y=Math.max(-my*560/S0,Math.min(my*560/S0,pc.y));return {w,h,x:(S0-w)/2+pc.x*S0/560,y:(S0-h)/2+pc.y*S0/560}}
