const STP=(()=>{let d="";for(let i=0;i<10;i++){const a=Math.PI/5*i-Math.PI/2,r=i%2?4.6:10;d+=(i?"L":"M")+(r*Math.cos(a)).toFixed(2)+" "+(r*Math.sin(a)).toFixed(2)}return d+"Z"})();
