function lsLessonQs(id,j){const bank=B[id]||[];if(!tplLayer(id)){const [a,b]=lsB(id,j);return bank.map((q,k)=>k).filter(k=>{const c=bank[k].lc??bank[k].c;return c>=a&&c<b})}const Q=lsQ(id);return Object.keys(Q).map(Number).filter(k=>Q[k]===j).sort((x,y)=>(bank[x].c-bank[y].c)||(x-y))}
