 if(j!=null&&!(full&&k!=="L")){const I=lsInfo(k,id,j);body=`<b>${LSN[k]} · Lesson ${j+1} of ${k==="L"?lsN(id):3}</b><small>${I.n} ${I.u} · about ${I.min} min</small>${dots}<button class="go lsgo" style="background:${col}" onclick="lsStart('${k}','${id}',${j})">${d.some(Boolean)?"Continue":"Start"}</button>`}
 else{body=`<b>${LSN[k]} · Complete ✓</b><small>${k==="L"?"Read any lesson again whenever you like.":"Keep it fresh with a practice round."}</small>${dots}${k==="L"?"":`<button class="go lsgo" style="background:${col}" onclick="document.querySelectorAll('.lsp').forEach(p=>p.remove());${k==="N"?`begin('${id}~n')`:`begin('${id}')`}">Practise · 10 questions</button>`}<div class="lsr">${[0,1,2].map(i=>`<button class="chipb" onclick="lsStart('${k}','${id}',${i})">Lesson ${i+1}</button>`).join("")}</div>`}
