const CPT=[["app","Phyzly learning"],["course","Course or study day"],["inserv","In-service or teaching session (attended)"],["clin","Clinical learning and on call"],["read","Reading or journal club"],["shad","Shadowing or peer learning"],["teach","Teaching others (delivered)"],["elearn","E-learning or self-study"],["sim","Simulation or practical session"],["mentor","Supervision or mentoring"],["refl","Reflective practice"],["oth","Other"]];
