function cpdAuto(t,m,ty){try{const now=new Date(),d=isoD(now),st=new Date(Math.max(now-m*60000,new Date(d+"T00:00:00").getTime())),se={tm:hm(st),m};S.cpd=S.cpd||[];const x=S.cpd.find(e=>e.auto&&e.d===d&&e.t===t);
 if(x){x.ss=(x.ss||[]).concat([se]).slice(-50);x.m=Math.min(1440,(x.m||0)+m);if(!x.tm||se.tm<x.tm)x.tm=se.tm;save();return x.id}
 const e={id:cpId(),d,t,ty,m,tm:se.tm,ss:[se],auto:1,otj:showApp()?true:undefined,r:{l:"",c:"",b:""}};S.cpd.unshift(e);save();return e.id}catch(e){return null}}
