const TGP=["MSK","Neuro","Respiratory","Cardiac","Critical care","Paediatrics","Older people","Pelvic health","Mental health","Community"];
const TGMAX=8;
function tgClean(a){const o=[],seen={};(Array.isArray(a)?a:[]).forEach(x=>{if(typeof x!=="string")return;const t=x.replace(/[^\p{L}\p{N} &'()\/+.-]/gu,"").replace(/\s+/g," ").trim().slice(0,30);const k=t.toLowerCase();if(t&&!seen[k]&&o.length<TGMAX){seen[k]=1;o.push(t)}});return o}
function tgUsed(){const c={};(S.cpd||[]).forEach(e=>(e.tg||[]).forEach(t=>{c[t]=(c[t]||0)+1}));return c}
function tgBlock(){cf.tg=tgClean(cf.tg);const on=new Set(cf.tg.map(t=>t.toLowerCase())),used=tgUsed();
 const own=Object.keys(used).filter(t=>!TGP.some(p=>p.toLowerCase()===t.toLowerCase())).sort((a,b)=>used[b]-used[a]||a.localeCompare(b));
 const extra=cf.tg.filter(t=>!TGP.concat(own).some(p=>p.toLowerCase()===t.toLowerCase()));
 const list=TGP.concat(own,extra);
 return `<div class="cfl">Tags <span style="font-weight:500;color:var(--mute)">(optional)</span></div><div class="chipw tgw" role="group" aria-label="Tags">${list.map(t=>`<button class="chipb${on.has(t.toLowerCase())?" on":""}" aria-pressed="${on.has(t.toLowerCase())}" data-t="${esc(t)}" onclick="tgTog(this.dataset.t)">${esc(t)}</button>`).join("")}</div>`+
  `<div class="tgadd"><input id="cf-tg" class="cin" maxlength="30" placeholder="Add your own, e.g. Amputee rehab" aria-label="Add your own tag" onkeydown="if(event.key==='Enter'){event.preventDefault();tgAdd()}"><button class="opt" onclick="tgAdd()">Add</button></div>`+
  (cf.tg.length>=TGMAX?`<p class="tag" style="margin:4px 0 0">That's the most tags for one entry (${TGMAX}).</p>`:"")}
function tgTog(t){cf.tg=tgClean(cf.tg);const i=cf.tg.findIndex(x=>x.toLowerCase()===String(t).toLowerCase());if(i>=0)cf.tg.splice(i,1);else if(cf.tg.length<TGMAX)cf.tg.push(t);cf.tg=tgClean(cf.tg);cfRe()}
function tgAdd(){const el=document.getElementById("cf-tg");const v=tgClean([el?el.value:""])[0];if(!v)return;cf.tg=tgClean(cf.tg);if(!cf.tg.some(x=>x.toLowerCase()===v.toLowerCase())&&cf.tg.length<TGMAX)cf.tg.push(v);cf.tg=tgClean(cf.tg);cfRe()}
function tgFilter(){const used=tgUsed(),ks=Object.keys(used).sort((a,b)=>used[b]-used[a]||a.localeCompare(b));if(!ks.length){cp.tf=null;return ""}if(cp.tf&&!used[cp.tf])cp.tf=null;
 return `<div class="cfl" style="margin-top:14px">Filter by tag</div><div class="chipw tgf" role="group" aria-label="Filter by tag"><button class="chipb${!cp.tf?" on":""}" aria-pressed="${!cp.tf}" onclick="cp.tf=null;home()">All</button>${ks.map(t=>`<button class="chipb${cp.tf===t?" on":""}" aria-pressed="${cp.tf===t}" data-t="${esc(t)}" onclick="cp.tf=this.dataset.t;home()">${esc(t)} <span style="opacity:.6">${used[t]}</span></button>`).join("")}</div>`}
const tgPills=e=>(e.tg||[]).length?`<span class="tgps">${e.tg.map(t=>`<span class="tgp">${esc(t)}</span>`).join("")}</span>`:"";
(function(){const st=document.createElement("style");st.textContent=`.tgadd{display:flex;gap:8px;margin-top:8px}.tgadd .cin{flex:1;margin:0}.tgadd .opt{width:auto;margin:0;padding:0 18px;white-space:nowrap}
.tgps{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}.tgp{display:inline-block;font-size:.75rem;font-weight:600;line-height:1;padding:4px 8px;border-radius:999px;background:var(--tint,#E8F0FF);color:var(--ink)}
.tgf .chipb span{font-weight:500}`;document.head.appendChild(st)})();
