 const e={id:"pm_"+m.id,pm:m.id,d:String(m.d),t:"Preceptorship meeting"+(rv?": "+rv:""),ty:"mentor",m:Math.max(0,Math.min(1440,Math.round(+m.m||0))),fw:"pm",r:p1?{p1}:{},sv:{k:"Preceptorship meeting",dir:"rcv",who:""}};
