 if((cf.fw||"std")==="sup"){n=[g("s1"),g("s3")].filter(Boolean).join("\n\n");ac=g("s2").split("\n").map(x=>x.replace(/^\s*(?:[-•*]|\d+[.)])\s*/,"").trim()).filter(Boolean).join("\n")}
