const daysTo=d=>Math.round((new Date(d+"T12:00:00")-new Date(isoD(new Date())+"T12:00:00"))/864e5);
const bk=(go,l)=>`<button class="lnk" onclick="${go}">‹ ${l}</button>`;
const CG=[["resp","Respiratory"],["neuro","Neurology"],["msk","Orthopaedics and MSK"],["acute","Acute and critical care"],["core","Core skills"]];
