 let ps="Set up";if(P&&P.start){const d=daysTo(P.start);ps=d>0?"Starts "+dFmt(P.start,{day:"numeric",month:"short"}):"Month "+Math.min(P.len,Math.floor(-d/30.44)+1)+" of "+P.len}
