 if(P&&P.start){t+="PRECEPTORSHIP\nStart: "+P.start+" · "+P.len+" months"+(P.who?" · Preceptor: "+P.who:"")+"\n\nReview points:\n"+preRvL().map(x=>"- "+x.n+" ("+preDue(x)+"): "+((P.ms||{})[x.id]?(typeof P.ms[x.id]==="string"?"held "+P.ms[x.id]:"done"):"not marked done")).join("\n")+"\n\nMeetings:\n"+((P.mt||[]).slice().sort((a,b)=>a.d.localeCompare(b.d)).map(m=>m.d+"\n"+(m.n||"-")+((m.ac||[]).length?"\nActions:\n"+m.ac.map(a=>"  ["+(a.done?"x":" ")+"] "+a.t).join("\n"):"")).join("\n\n")||"-")+"\n\nProgramme sessions:\n"+(preSess().slice().reverse().map(e=>"- "+e.d+": "+e.t+" ("+fmtH(e.m||0)+")"+(cpHas(e)?", reflected":"")+((e.ph||[]).length?", "+e.ph.length+" attachment"+(e.ph.length>1?"s":""):"")).join("\n")||"-")+"\n\nGoals:\n"+((preGl().map(g=>"["+(g.done?"x":" ")+"] "+g.t+(g.by&&!g.done?" (by "+g.by+")":"")).join("\n"))||"-")+"\n\n"}
 const V=cmV(),cp2=S.cpd||[],rows=[];
 CG.forEach(g=>{compAll().filter(c=>c.g===g[0]).forEach(c=>{const v=V[c.id];if(!v||(!v.l&&!v.n&&!v.so&&!(v.ev||[]).length&&!(v.ph||[]).length))return;rows.push("- "+g[1]+": "+c.t+" — "+LVN[v.l||0]+(v.d?" ("+v.d+")":"")+(v.so?", signed off in trust paperwork":"")+(v.n?"\n  Notes: "+v.n:"")+((v.ev||[]).length?"\n  Evidence: "+v.ev.map(i=>(cp2.find(e=>e.id===i)||{t:"(removed entry)"}).t).join("; "):"")+((v.ph||[]).length?"\n  Files attached in Phyzly: "+v.ph.length:""))})});
