const ksbDef=()=>{const a=[];KSBD.forEach((t,i)=>{t[0].forEach((x,j)=>a.push({id:"s"+i+"_"+j,g:i,c:KSBT[i][1]+"-S"+(j+1),t:x}));t[1].forEach((x,j)=>a.push({id:"k"+i+"_"+j,g:i,c:KSBT[i][1]+"-K"+(j+1),t:x}))});return a};
const ksbCustom=()=>!!(S.ksb&&S.ksb.items&&S.ksb.items.length);
