const ehE=(cx,cy,rx,ry)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const ehR=(x,y,w,h,r)=>`M${x+r} ${y}h${w-2*r}a${r} ${r} 0 0 1 ${r} ${r}v${h-2*r}a${r} ${r} 0 0 1 ${-r} ${r}h${-(w-2*r)}a${r} ${r} 0 0 1 ${-r} ${-r}v${-(h-2*r)}a${r} ${r} 0 0 1 ${r} ${-r}Z`;
const ehC=(x1,y1,x2,y2,w)=>{const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy),ux=dx/l,uy=dy/l,r=w/2,nx=-uy*r,ny=ux*r;return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`};
/* part: [id, name, type, path, extra]  type f bone/soft fill, x hollow, t tendon, n nerve, a artery, g ligament band (fill), l line (stroke only), h hidden until highlighted (stroke), hf hidden fill */
const ehPart=(p,hi)=>{const [id,nm,t,d,w]=p,W=w||5;
 if(t==="l"||t==="h"){if(t==="h"&&!hi)return "";return `<path d="${d}" fill="none" stroke="${hi?"var(--pri)":"var(--mute)"}" stroke-width="${hi?W+2:W}" stroke-linecap="round" stroke-linejoin="round"${hi?"":' stroke-opacity=".65"'}/>`}
 if(t==="dl"){return `<path d="${d}" fill="none" stroke="${hi?"var(--pri)":"var(--mute)"}" stroke-width="${hi?W+1:2}" stroke-dasharray="5 4" stroke-linecap="round"/>`}
 if(t==="nl"){return hi?`<path d="${d}" fill="none" stroke="var(--pri)" stroke-width="${W+3}" stroke-linecap="round"/>`:`<path d="${d}" fill="none" stroke="#A87800" stroke-width="${W+3}" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#FFD23F" stroke-width="${W}" stroke-linecap="round"/>`}
 if(hi)return `<path d="${d}" ${EH_H}/>`;
 const st={f:EH_S,x:EH_X,t:EH_T,n:EH_N,a:EH_A,g:'fill="#F7D9A8" stroke="#B7791F" stroke-width="2" stroke-linejoin="round"',hf:"hidden"}[t];
 return st==="hidden"?"":`<path d="${d}" ${st}/>`};
