 const body=mvBody3()+hand([212.3,272],[212.6,292],6)+armF;
 const SAG=[[mid,top,zb],[mid,top,zf],[mid,bot,zf],[mid,bot,zb]],PARA=[[mid+.6,top,zb],[mid+.6,top,zf],[mid+.6,bot,zf],[mid+.6,bot,zb]],COR=[[xl,top,0],[xr,top,0],[xr,bot,0],[xl,bot,0]],TRA=[[xl,-1.6,zb],[xr,-1.6,zb],[xr,-1.6,zf],[xl,-1.6,zf]];
 const head=(t,sub)=>qz?"":T(160,22,t,{b:1,fs:13.5})+T(160,38,sub,{fs:11.5,col:M});
 let s="",al="Planes of the body",cap="Three-quarter view, right side nearest";
