  s+=`<path d="M${sx+40} ${sy}A40 40 0 0 0 ${(sx+40*Math.cos(a)).toFixed(1)} ${(sy-40*Math.sin(a)).toFixed(1)}" fill="none" stroke="${P}" stroke-width="1.5"/>`+T(sx+50,sy-8,"30 to 45°",{fs:11.5,col:P,b:1,a:"start"});
