 const thigh=seg(64,13,10),shank=seg(62,10,7),foot=FM.cr([[-6,-6],[4,-8],[30,-2],[34,4],[28,8],[-8,8],[-10,0]]),trunk=FM.cr([[-14,0],[14,0],[16,-60],[8,-74],[-10,-74],[-18,-60]]);
