 const crs=pts=>{let d=`M${X(pts[0][0])} ${Y(pts[0][1])}`;for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i];d+=`Q${X(a[0])} ${Y(a[1])} ${X((a[0]+b[0])/2)} ${Y((a[1]+b[1])/2)}`}const z=pts[pts.length-1];return d+`L${X(z[0])} ${Y(z[1])}`};
