 s+=`<ellipse cx="${X(1.12)}" cy="${Y(1.15)}" rx="${.16*u}" ry="${.42*u}" fill="var(--musc)" fill-opacity="${on("muscle")?1:.85}" stroke="${on("muscle")?P:M}" stroke-width="${on("muscle")?3:1}"/>`;
 s+=`<ellipse cx="${X(1.15)}" cy="${Y(3.52)}" rx="${.16*u}" ry="${.2*u}" fill="${on("skin")?P:"#F2C9A4"}" fill-opacity=".9" stroke="${M}" stroke-width="1"/>`;
