  s+=L(X(-.25),Y(-1.3),80,22,"Brain","end")+L(X(-.04),Y(1.6),80,140,"Spinal cord","end")+L(X(.34),Y(.18),204,36,"Nerve root")+L(X(1.18),Y(.62),204,74,"Peripheral nerve")+L(X(1.27),Y(1.2),204,116,"Muscle")+L(X(1.27),Y(3.5),204,190,"Skin");
  s+=`<rect x="8" y="238" width="12" height="8" rx="2" fill="#8C76C4"/>`+T(26,246,"central: brain and cord",{fs:11.5,a:"start",col:M})+`<rect x="8" y="256" width="12" height="8" rx="2" fill="#C9A23A"/>`+T(26,264,"peripheral: everything else",{fs:11.5,a:"start",col:M});
  const KY={sens:[P,"sensory: skin to cord","7 4"],lmn:[OR,"lower motor neurone: cord to muscle",""],umn:[OR,"upper motor neurone: brain to cord",""]};
