const iv={v:"hub",th:null,q:null,rev:false,sd:null,st:null,dr:null,p:null,m:null,mn:5,mf:"all",rec:false};
let ivT=null,ivStream=null,ivMR=null;
const ivS=()=>{S.iv=S.iv||{};const o=S.iv;o.pr=o.pr||{};o.st=o.st||{};o.prio=o.prio||{};o.mk=o.mk||[];return o};
const ivLk=()=>pwOn();
const ivPL=()=>ivLk()?' <span class="pl">PLUS</span>':"";
const ivFree=v=>["hub","bank","theme","q","star","starq","tips"].includes(v);
const ivTh=id=>IVQ.themes.find(t=>t.id===id)||{n:"",ic:""};
const ivQ=id=>IVQ.questions.find(q=>q.id===id);
const ivQLk=q=>!q.free&&ivLk();
const ivMark=s=>esc(s).replace(/\[([^\]]+)\]/g,'<mark class="ph">$1</mark>');
const ivUl=a=>`<ul class="ivl">${a.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`;
const mss=ms=>{const s=Math.max(0,Math.ceil(ms/1000));return Math.floor(s/60)+":"+String(s%60).padStart(2,"0")};
const stOf=id=>ivS().st[id]||null;
const stReady=id=>{const x=stOf(id);return !!x&&["s","t","a","r"].every(k=>(x[k]||"").trim().length>=20)};
const stStarted=id=>{const x=stOf(id);return !!x&&["s","t","a","r"].some(k=>(x[k]||"").trim())};
const words=t=>(t||"").trim().split(/\s+/).filter(Boolean).length;
const showIv=()=>S.ivTools!=null?!!S.ivTools:S.role!=="exp";
function openIv(v){ivStop("hub");if(v&&!ivFree(v)&&ivLk())return openSub("iv");tab="cpd";curPack=null;pf="iv";iv.v=v||"hub";iv.rev=false;home();window.scrollTo(0,0)}
function ivGo(v,o){ivStop(v);if(!ivFree(v)&&ivLk())return openSub("iv");Object.assign(iv,o||{});iv.v=v;tab="cpd";curPack=null;pf="iv";home();window.scrollTo(0,0)}
function ivBackBtn(v,l,o){return `<button class="lnk" onclick='ivGo(${JSON.stringify(v)},${JSON.stringify(o||{})})'>‹ ${esc(l)}</button>`}
function ivHome(){const v=iv.v;if(v!=="mrun")ivStop(v);
 const f={hub:ivHub,bank:ivBank,theme:ivTheme,q:ivQView,star:ivStar,starq:ivStarQ,stories:ivStories,story:ivStory,prio:ivPrioList,ptask:ivPTask,mock:ivMock,mrun:ivMRun,mend:ivMEnd,tips:ivTips}[v]||ivHub;
 app.innerHTML=head()+tabs()+f()+foot()}
function ivRow(ic,c,n,d,st,on,lk){return `<button class="trk" onclick="${on}"><span class="tile" style="background:${c}">${ic}</span><span class="tx"><b>${n}${lk?' <span class="pl">PLUS</span>':""}</b><small>${d}</small></span><span class="st">${st}</span></button>`}
function ivHub(){
 const s=ivS(),n=IVQ.questions.length,pr=IVQ.questions.filter(q=>s.pr[q.id]).length,sr=IVX.stories.filter(x=>stReady(x.id)).length,pd=Object.keys(s.prio).length,mk=s.mk.length,lk=ivLk();
 return bk("pf='home';home()","Portfolio")+`<div class="ivh"><span>💼</span><h1>Interview prep</h1><p>Band 5 rotational interviews: practise the questions, build your examples, then run a mock.</p></div>`+ivDateBox()+
 `<div class="stats"><div class="stat"><strong>${pr}/${n}</strong>questions practised</div><div class="stat"><strong>${sr}/${IVX.stories.length}</strong>stories ready</div></div>`+
 `<div class="note">Draft content. It will be reviewed by clinicians who sit on band 5 interview panels. Always check your own trust's values and the job's person specification.</div>`+
 `<div class="sec">Prepare</div>`+
 ivRow("❓","#1A6BFF","Question bank",`${n} questions in ${IVQ.themes.length} themes`,pr?pr+" done":"Start","ivGo('bank')")+
 ivRow("⭐","#D97706","STAR trainer","Structure answers that score",s.star?"Best "+s.star+"/8":"Start","ivGo('star')")+
 ivRow("📖","#0F9D8A","My stories","Your examples, ready for any question",sr+" of "+IVX.stories.length,"ivGo('stories')",lk)+
 `<div class="sec">Practise</div>`+
 ivRow("⚖️","#8A4DFF","Prioritisation task","Rank a caseload and justify it",pd?pd+" of "+IVX.prio.length:"Start","ivGo('prio')",lk)+
 ivRow("🎙️","#E8590C","Mock interview","Timed questions, answer out loud",mk?mk+" done":"Start","ivGo('mock')",lk)+
 ivRow("💡","#2E9E5B","Interview day tips","Before, on the day and after",IVX.tips.length+" tips","ivGo('tips')");
}
function ivBank(){const s=ivS();
 return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 2px">Question bank</h1><p class="tag" style="margin:0 0 12px">Read the question, plan your answer out loud, then reveal what the panel is looking for.</p>`+
 IVQ.themes.map(t=>{const qs=IVQ.questions.filter(q=>q.th===t.id),d=qs.filter(q=>s.pr[q.id]).length;return `<button class="opt" onclick="ivGo('theme',{th:'${t.id}'})"><div class="row"><b>${t.ic} ${esc(t.n)}</b><span>${d}/${qs.length}</span></div><small style="color:var(--mute)">${esc(t.d)}</small></button>`}).join("")}
const CONF=[["Not yet","🔴"],["Getting there","🟠"],["Confident","🟢"]];
function ivTheme(){const s=ivS(),t=ivTh(iv.th),qs=IVQ.questions.filter(q=>q.th===iv.th);
 return ivBackBtn("bank","Question bank")+`<h1 style="font-size:1.5rem;margin:6px 0 2px">${t.ic} ${esc(t.n)}</h1><p class="tag" style="margin:0 0 12px">${esc(t.d)}</p>`+
 qs.map(q=>{const p=s.pr[q.id],lk=ivQLk(q);return `<button class="opt" onclick="${lk?"openSub('iv')":`ivGo('q',{q:'${q.id}',rev:false})`}"><div class="row"><b style="font-weight:600">${esc(q.q)}${lk?' <span class="pl">PLUS</span>':""}</b><span>${p?CONF[p.c][1]:""}</span></div></button>`}).join("")}
function ivQView(){const q=ivQ(iv.q);if(!q)return ivBank();if(ivQLk(q)){setTimeout(()=>openSub("iv"),0);return ""}
 const s=ivS(),t=ivTh(q.th),ask=q.th==="ask",rev=iv.rev||ask,qs=IVQ.questions.filter(x=>x.th===q.th&&!ivQLk(x)),i=qs.indexOf(q),p=s.pr[q.id];
 let o=ivBackBtn("theme",t.n,{th:q.th})+`<p class="tag" style="margin:8px 0 2px">${t.ic} ${esc(t.n)}${q.star?" · STAR question":""}</p><h1 class="ivq">${esc(q.q)}</h1>`;
 o+=`<div class="note"><b>${ask?"Why it works":"What they're testing"}</b><br>${esc(q.test)}</div>`;
 if(!rev)o+=`<p class="tag">Plan your answer out loud first.${q.star?" It's a 'tell me about a time' question, so use STAR: situation, task, action, result.":""}</p><button class="go" onclick="iv.rev=true;ivHome()">Reveal what a strong answer includes</button>`;
 else{
  o+=`<div class="sec">${ask?"What to listen for":"A strong answer includes"}</div>`+ivUl(q.strong)+(q.avoid&&q.avoid.length?`<div class="sec">Avoid</div>`+ivUl(q.avoid):"");
  o+=`<div class="sec">${ask?"How to ask it":"Outline to adapt"}</div><div class="ivo">${ivMark(q.outline)}</div><p class="tag" style="font-size:.8rem">Highlighted parts are for your own experience. Don't learn it word for word.</p>`;
  if(q.star&&!ivLk()){const fit=IVX.stories.filter(x=>x.tags.some(g=>(q.tags||[]).includes(g)));
   o+=`<div class="sec">Stories that fit</div>`+(fit.length?fit.slice(0,3).map(x=>`<button class="opt" onclick="ivGo('story',{st:'${x.id}',dr:null})"><div class="row"><b>📖 ${esc(x.n)}</b><span>${stReady(x.id)?"Ready":stStarted(x.id)?"Draft":"Write it"}</span></div></button>`).join(""):`<p class="tag">Build one in My stories.</p>`)}
  o+=`<div class="sec">How confident are you?</div><div class="seg2">${CONF.map(([l,e],k)=>`<button class="opt ${p&&p.c===k?"ok":""}" onclick="ivConf('${q.id}',${k})">${e} ${l}</button>`).join("")}</div>`;
 }
 o+=`<div class="tabs" style="margin-top:12px">${i>0?`<button class="opt" style="text-align:center" onclick="ivGo('q',{q:'${qs[i-1].id}',rev:false})">‹ Previous</button>`:""}${i<qs.length-1?`<button class="opt" style="text-align:center" onclick="ivGo('q',{q:'${qs[i+1].id}',rev:false})">Next ›</button>`:""}</div>`;
 return o}
function ivConf(id,k){const s=ivS(),was=s.pr[id];s.pr[id]={c:k,d:isoD(new Date())};if(!was){S.xpT=(S.xpT||0)+5;sfx("ok",2)}save();ivHome()}
/* STAR trainer */
function ivStar(){const s=ivS();
 return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 2px">⭐ STAR trainer</h1><p class="tag" style="margin:0 0 12px">The structure panels listen for in every 'tell me about a time' answer.</p>`+
 IVX.starLearn.map((c,k)=>`<div class="ivc"><b><span class="ivn">${k+1}</span>${esc(c.t)}</b><p>${esc(c.b)}</p></div>`).join("")+
 `<button class="go" onclick="ivStarGo()">Start drill · 8 questions</button>${s.star?`<p class="tag" style="text-align:center;margin-top:8px">Your best: ${s.star}/8</p>`:""}`}
function ivStarGo(){iv.sd={qs:shuffle(IVX.starDrills.slice()).slice(0,8),i:0,sc:0,pk:null};ivGo("starq")}
function ivStarQ(){const d=iv.sd;if(!d)return ivStar();
 if(d.i>=d.qs.length){const s=ivS(),b=s.star||0;if(!d.saved){d.saved=1;if(d.sc>b)s.star=d.sc;S.xpT=(S.xpT||0)+d.sc*5;save();sfx("fin",d.sc/8*100);if(d.sc>=7)confetti(50)}
  return `<div class="ivh"><span>${d.sc>=7?"🏆":d.sc>=5?"👏":"💪"}</span><h1>${d.sc}/8</h1><p>${d.sc>=7?"You know your STAR.":d.sc>=5?"Nearly there. Run it again to lock it in.":"Have another read of the cards, then try again."}</p></div><button class="go" onclick="ivStarGo()">Go again</button><button class="opt" style="text-align:center;margin-top:10px" onclick="ivGo('star')">Back to STAR trainer</button>`}
 const q=d.qs[d.i],pk=d.pk;
 return `<div class="bar"><button class="lnk" onclick="ivGo('star')" aria-label="Close">✕</button><div class="track"><div class="fill" style="width:${d.i/d.qs.length*100}%"></div></div></div><h2 class="ivq" style="font-size:1.15rem">${esc(q.q)}</h2>`+
 q.o.map((x,k)=>`<button class="opt ${pk!=null?(k===q.a?"ok":k===pk?"bad":""):""}" ${pk!=null?"disabled":""} onclick="ivStarPick(${k})">${esc(x)}</button>`).join("")+
 (pk!=null?`<div class="fb ${pk===q.a?"ok":"bad"}"><b>${pk===q.a?"Right":"Not quite"}</b>${esc(q.why)}</div><button class="go" onclick="iv.sd.i++;iv.sd.pk=null;ivHome();window.scrollTo(0,0)">Continue</button>`:"")}
function ivStarPick(k){const d=iv.sd,q=d.qs[d.i];if(d.pk!=null)return;d.pk=k;if(k===q.a){d.sc++;sfx("ok",d.sc)}else sfx("bad");ivHome()}
/* My stories */
function ivStories(){
 return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 2px">📖 My stories</h1><p class="tag" style="margin:0 0 12px">Write 6 to 8 real examples once, then adapt them to whatever the panel asks. Saved on this device only.</p>`+
 IVX.stories.map(x=>`<button class="opt" onclick="ivGo('story',{st:'${x.id}',dr:null})"><div class="row"><b>${esc(x.n)}</b><span>${stReady(x.id)?"✅ Ready":stStarted(x.id)?"Draft":"Not started"}</span></div><small style="color:var(--mute)">${x.tags.map(esc).join(" · ")}</small></button>`).join("")}
const STL={s:"Situation",t:"Task",a:"Action",r:"Result and reflection"};
function ivStory(){const x=IVX.stories.find(y=>y.id===iv.st);if(!x)return ivStories();
 if(!iv.dr)iv.dr=Object.assign({s:"",t:"",a:"",r:""},stOf(x.id)||{});const d=iv.dr,w=["s","t","a","r"].reduce((n,k)=>n+words(d[k]),0);
 const qs=IVQ.questions.filter(q=>q.star&&q.tags&&q.tags.some(g=>x.tags.includes(g))).slice(0,4);
 return ivBackBtn("stories","My stories")+`<h1 style="font-size:1.5rem;margin:6px 0 2px">${esc(x.n)}</h1><p class="tag" style="margin:0 0 10px">${esc(x.hint)}</p>`+
 ["s","t","a","r"].map(k=>`<label class="cfl" for="iv-${k}">${STL[k]}</label><div class="tag" style="margin:0 0 4px">${esc(x.prompts[k])}</div><textarea id="iv-${k}" class="cin" rows="${k==="a"?5:3}" maxlength="1500" oninput="iv.dr.${k}=this.value;ivWc()">${esc(d[k]||"")}</textarea>`).join("")+
 `<p class="tag" id="ivwc">${ivWcTxt(w)}</p><button class="go" onclick="ivStSave()">Save story</button>`+
 (qs.length?`<div class="sec">Questions this could answer</div>`+qs.map(q=>`<button class="opt" onclick="${ivQLk(q)?"openSub('iv')":`ivGo('q',{q:'${q.id}',rev:false})`}">${esc(q.q)}</button>`).join(""):"")}
const ivWcTxt=w=>w?`${w} words · about ${Math.max(1,Math.round(w/130*60/15)*15)} seconds spoken. Aim for 1½ to 2 minutes, with most of it on Action.`:"Bullet points are fine. You'll say it in your own words on the day.";
function ivWc(){const d=iv.dr,w=["s","t","a","r"].reduce((n,k)=>n+words(d[k]),0),e=document.getElementById("ivwc");if(e)e.textContent=ivWcTxt(w)}
function ivStSave(){const s=ivS(),d=iv.dr,was=stReady(iv.st);if(["s","t","a","r"].every(k=>!(d[k]||"").trim()))delete s.st[iv.st];else s.st[iv.st]={s:d.s.slice(0,1500),t:d.t.slice(0,1500),a:d.a.slice(0,1500),r:d.r.slice(0,1500),d:isoD(new Date())};save();
 if(!was&&stReady(iv.st)){S.xpT=(S.xpT||0)+20;save();celebrate("Story ready")}else toast("Saved");ivGo("stories",{dr:null})}
/* Prioritisation */
function ivPrioList(){const s=ivS();
 return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 2px">⚖️ Prioritisation task</h1><p class="tag" style="margin:0 0 12px">Many panels give you a patient list to rank and talk through. Order it, then compare your reasoning.</p>`+
 IVX.prio.map(p=>`<button class="opt" onclick="ivPStart('${p.id}')"><div class="row"><b>${esc(p.n)}</b><span>${s.prio[p.id]!=null?"Best "+s.prio[p.id]+"%":"Start"}</span></div></button>`).join("")}
function ivPStart(id){const p=IVX.prio.find(x=>x.id===id);let o=shuffle(p.pts.map(x=>x.id));if(o.join()===p.order.join())o.reverse();iv.p={id,ord:o,chk:false};ivGo("ptask")}
function ivPMove(i,dx){const o=iv.p.ord,j=i+dx;if(j<0||j>=o.length)return;[o[i],o[j]]=[o[j],o[i]];hap("tap");ivHome()}
function ivPScore(p,o){let t=0;o.forEach((id,i)=>{t+=Math.max(0,3-Math.abs(i-p.order.indexOf(id)))});return Math.round(t/(3*o.length)*100)}
function ivPTask(){const st=iv.p;if(!st)return ivPrioList();const p=IVX.prio.find(x=>x.id===st.id),pt=id=>p.pts.find(x=>x.id===id);
 let o=ivBackBtn("prio","Prioritisation task")+`<h1 style="font-size:1.4rem;margin:6px 0 4px">${esc(p.n)}</h1><div class="note">${esc(p.ctx)}</div>`;
 if(!st.chk){o+=`<p class="tag">Put the most urgent at the top. Say why out loud as you go, as you would to the panel.</p>`+
  st.ord.map((id,i)=>{const x=pt(id);return `<div class="ivp"><span class="ivn">${i+1}</span><div class="ivpt"><b>${esc(x.t)}</b><small>${esc(x.d)}</small></div><div class="ivud"><button aria-label="Move up" ${i===0?"disabled":""} onclick="ivPMove(${i},-1)">▲</button><button aria-label="Move down" ${i===st.ord.length-1?"disabled":""} onclick="ivPMove(${i},1)">▼</button></div></div>`}).join("")+
  `<button class="go" onclick="ivPCheck()">Check my order</button>`}
 else{const sc=ivPScore(p,st.ord);
  o+=`<div class="ivh" style="margin:8px 0"><span>${sc>=85?"🎯":sc>=60?"👍":"🤔"}</span><h1>${sc}% match</h1><p>There's rarely a single right order. The panel wants safe, clear reasoning.</p></div><div class="sec">Suggested order</div>`+
  p.order.map((id,i)=>{const x=pt(id),me=st.ord.indexOf(id);return `<div class="ivp ${me===i?"ok":""}"><span class="ivn">${i+1}</span><div class="ivpt"><b>${esc(x.t)}</b><small>${esc(p.why[id]||"")}</small><small class="ivme">You put this ${me===i?"in the same place ✓":"at number "+(me+1)}</small></div></div>`}).join("")+
  `<div class="sec">What the panel looks for</div><p>${esc(p.notes)}</p><button class="go" onclick="ivPStart('${p.id}')">Try again</button><button class="opt" style="text-align:center;margin-top:10px" onclick="ivGo('prio')">Another list</button>`}
 return o}
function ivPCheck(){const st=iv.p,p=IVX.prio.find(x=>x.id===st.id),s=ivS(),sc=ivPScore(p,st.ord);st.chk=true;if(s.prio[p.id]==null||sc>s.prio[p.id])s.prio[p.id]=sc;S.xpT=(S.xpT||0)+10;save();sfx("fin",sc);ivHome();window.scrollTo(0,0)}
/* Mock interview */
const MOCKF={all:["Mixed",null],clin:["Clinical and prioritising",["clin","prio","safe","cons"]],beh:["Values and behaviour",["values","mdt","prof","cpd","safe"]]};
const THINK=30000,ANS=120000;
function ivMock(){const s=ivS(),canRec=!!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia&&window.MediaRecorder);
 return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 2px">🎙️ Mock interview</h1><p class="tag" style="margin:0 0 12px">Each question gives you 30 seconds to think and 2 minutes to answer out loud. Then tick off what you covered.</p>`+
 `<div class="sec">How many questions?</div><div class="seg2">${[3,5,8].map(n=>`<button class="opt ${iv.mn===n?"ok":""}" onclick="iv.mn=${n};ivHome()">${n}</button>`).join("")}</div>`+
 `<div class="sec">Focus</div><div class="seg2">${Object.entries(MOCKF).map(([k,v])=>`<button class="opt ${iv.mf===k?"ok":""}" onclick="iv.mf='${k}';ivHome()">${v[0]}</button>`).join("")}</div>`+
 (canRec?`<button class="opt" style="margin-top:6px" onclick="iv.rec=!iv.rec;ivHome()"><div class="row"><b>Record my answers</b><span>${iv.rec?"On":"Off"}</span></div><small style="color:var(--mute)">Play yourself back after each answer. Recordings stay on this device and are deleted when you leave.</small></button>`:"")+
 `<button class="go" style="margin-top:8px" onclick="ivMStart()">Start mock interview</button>`+
 (s.mk.length?`<div class="sec">Past mocks</div>`+s.mk.slice(-5).reverse().map(m=>`<div class="lr"><div class="nm">${esc(m.d)}<small>${m.n} questions · ${esc((MOCKF[m.f]||MOCKF.all)[0])}</small></div><b class="pt">${m.sc}%</b></div>`).join(""):"")}
function ivMPick(){const f=MOCKF[iv.mf][1],pool=shuffle(IVQ.questions.filter(q=>q.th!=="ask"&&q.th!=="why"&&(!f||f.includes(q.th)))),why=shuffle(IVQ.questions.filter(q=>q.th==="why"))[0],out=[why],seen=new Set();
 pool.forEach(q=>{if(out.length<iv.mn&&!seen.has(q.th)){seen.add(q.th);out.push(q)}});pool.forEach(q=>{if(out.length<iv.mn&&!out.includes(q))out.push(q)});return out}
async function ivMStart(){iv.m={qs:ivMPick(),i:0,ph:"think",t0:Date.now(),recs:[],ticks:[],recErr:null};
 if(iv.rec){try{ivStream=await navigator.mediaDevices.getUserMedia({audio:true})}catch(e){ivStream=null;iv.m.recErr=1}}
 ivGo("mrun");ivRun()}
function ivRun(){clearInterval(ivT);ivT=setInterval(ivTick,250);if(iv.m.ph==="ans")ivRecStart()}
function ivStop(nx){clearInterval(ivT);ivT=null;try{if(ivMR&&ivMR.state!=="inactive")ivMR.stop()}catch(e){}if(nx!=="mrun"&&nx!=="mend"&&ivStream){ivStream.getTracks().forEach(t=>t.stop());ivStream=null}}
function ivRecStart(){if(!ivStream)return;try{const ch=[],i=iv.m.i;ivMR=new MediaRecorder(ivStream);ivMR.ondataavailable=e=>{if(e.data&&e.data.size)ch.push(e.data)};ivMR.onstop=()=>{if(ch.length&&iv.m){iv.m.recs[i]=URL.createObjectURL(new Blob(ch,{type:ch[0].type||"audio/webm"}));if(iv.v==="mrun"&&iv.m.ph==="rate"&&iv.m.i===i)ivHome()}};ivMR.start()}catch(e){iv.m.recErr=1}}
function ivTick(){const m=iv.m;if(!m||iv.v!=="mrun"||pf!=="iv"||tab!=="cpd"){ivStop("away");return}if(m.ph==="rate")return;const dur=m.ph==="think"?THINK:ANS,left=dur-(Date.now()-m.t0),e=document.getElementById("mt"),r=document.getElementById("mr");
 if(e)e.textContent=mss(left);if(r)r.style.strokeDashoffset=String(283*(1-Math.max(0,left)/dur));if(left<=0)ivMNext()}
function ivMNext(){const m=iv.m;if(m.ph==="think"){m.ph="ans";m.t0=Date.now();hap("on");ivHome();ivRun()}else if(m.ph==="ans"){m.ph="rate";m.ticks[m.i]=m.ticks[m.i]||[];clearInterval(ivT);try{if(ivMR&&ivMR.state!=="inactive")ivMR.stop()}catch(e){}hap("on");ivHome();window.scrollTo(0,0)}}
function ivMTick(k){const t=iv.m.ticks[iv.m.i];const j=t.indexOf(k);if(j<0)t.push(k);else t.splice(j,1);hap("tap");ivHome()}
function ivMCont(){const m=iv.m;m.i++;if(m.i>=m.qs.length){ivMFinish();return}m.ph="think";m.t0=Date.now();ivHome();window.scrollTo(0,0);ivRun()}
function ivMFinish(){const m=iv.m,s=ivS(),per=m.qs.map((q,i)=>Math.round((m.ticks[i]||[]).length/q.strong.length*100)),sc=Math.round(per.reduce((a,b)=>a+b,0)/per.length);
 m.per=per;m.sc=sc;s.mk.push({iso:isoD(new Date()),d:new Date().toLocaleDateString("en-GB",{day:"numeric",month:"short"}),n:m.qs.length,f:iv.mf,sc});if(s.mk.length>30)s.mk=s.mk.slice(-30);S.xpT=(S.xpT||0)+m.qs.length*10;save();
 sfx("fin",sc);if(sc>=80)confetti(50);ivGo("mend")}
function ivMRun(){const m=iv.m;if(!m)return ivMock();const q=m.qs[m.i],t=ivTh(q.th);
 let o=`<div class="bar"><button class="lnk" onclick="ivGo('mock')" aria-label="Leave">✕</button><div class="track"><div class="fill" style="width:${m.i/m.qs.length*100}%"></div></div><span class="tag" style="margin:0 0 0 8px;white-space:nowrap">${m.i+1} of ${m.qs.length}</span></div>`;
 o+=`<p class="tag" style="margin:4px 0 2px">${t.ic} ${esc(t.n)}</p><h1 class="ivq">${esc(q.q)}</h1>`;
 if(m.ph!=="rate"){const dur=m.ph==="think"?THINK:ANS,left=dur-(Date.now()-m.t0);
  o+=`<div class="tmr ${m.ph}"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="45" class="bg"/><circle id="mr" cx="50" cy="50" r="45" class="fg" style="stroke-dashoffset:${283*(1-Math.max(0,left)/dur)}"/></svg><div><b id="mt">${mss(left)}</b><small>${m.ph==="think"?"Thinking time":"Answer out loud"}</small></div></div>`+
  (m.ph==="ans"&&ivStream?`<p class="tag" style="text-align:center">🔴 Recording</p>`:"")+(m.recErr&&m.i===0&&m.ph==="think"?`<div class="note">Recording isn't available here. Answer out loud anyway. It works in the app version.</div>`:"")+
  `<button class="go" onclick="ivMNext()">${m.ph==="think"?"I'm ready to answer":"I've finished my answer"}</button>`}
 else{const tk=m.ticks[m.i]||[];
  o+=`<div class="sec">Tick what you covered</div>`+q.strong.map((x,k)=>`<button class="ivck ${tk.includes(k)?"on":""}" onclick="ivMTick(${k})"><span>${tk.includes(k)?"✓":""}</span>${esc(x)}</button>`).join("")+
  (m.recs[m.i]?`<div class="sec">Your answer</div><audio controls src="${m.recs[m.i]}" style="width:100%"></audio>`:"")+
  `<details class="ivd"><summary>Outline to compare</summary><div class="ivo">${ivMark(q.outline)}</div></details><button class="go" onclick="ivMCont()">${m.i<m.qs.length-1?"Next question":"Finish interview"}</button>`}
 return o}
function ivMEnd(){const m=iv.m;if(!m||m.sc==null)return ivMock();const ask=IVQ.questions.filter(q=>q.th==="ask");
 return `<div class="ivh"><span>${m.sc>=80?"🏆":m.sc>=55?"👏":"💪"}</span><h1>${m.sc}% covered</h1><p>Based on what you ticked. Coverage matters, but so do clear structure and a calm delivery.</p></div>`+
 `<div class="sec">Question by question</div>`+m.qs.map((q,i)=>`<button class="opt" style="${m.recs[i]?"margin-bottom:4px":""}" onclick="ivGo('q',{q:'${q.id}',rev:true})"><div class="row"><b style="font-weight:600">${esc(q.q)}</b><span>${m.per[i]}%</span></div></button>${m.recs[i]?`<audio controls src="${m.recs[i]}" style="width:100%;margin:0 0 12px"></audio>`:""}`).join("")+
 `<div class="sec">"Do you have any questions for us?"</div><p class="tag" style="margin:0 0 8px">Every interview ends with this. Have two ready.</p>`+ask.slice(0,2).map(q=>`<div class="ivc"><b>${esc(q.q)}</b><p>${esc(q.test)}</p></div>`).join("")+
 `<button class="go" onclick="ivMStart()">Another mock</button><button class="opt" style="text-align:center;margin-top:10px" onclick="ivGo('hub')">Back to Interview prep</button>`}
function ivTips(){return ivBackBtn("hub","Interview prep")+`<h1 style="font-size:1.6rem;margin:6px 0 12px">💡 Interview day tips</h1>`+IVX.tips.map((c,k)=>`<div class="ivc"><b><span class="ivn">${k+1}</span>${esc(c.t)}</b><p>${esc(c.b)}</p></div>`).join("")}


/* interview date + countdown */
function ivDays(){const d=S.iv&&S.iv.date;return d?daysTo(d):null}
function ivPortSt(){const n=ivDays();if(n!=null&&n>=0)return n===0?"Interview today":n===1?"Interview tomorrow":"Interview in "+n+" days";const k=Object.keys((S.iv||{}).pr||{}).length;return k?k+" questions practised":"Get ready"}
function ivDateBox(){const s=ivS(),n=ivDays();
 if(iv.dt)return `<div class="ivc"><b>📅 When is your interview?</b><input id="ivdt" class="cin" type="date" min="${isoD(new Date())}" value="${esc(s.date||"")}" style="margin-top:8px"><input id="ivpost" class="cin" maxlength="60" placeholder="Post or trust (optional)" value="${esc(s.post||"")}" style="margin-top:8px"><div class="tabs"><button class="opt" style="text-align:center" onclick="iv.dt=false;ivHome()">Cancel</button><button class="go" onclick="ivDateSave()">Save</button></div>${iv.dterr?`<p class="tag" style="color:var(--bad)">${esc(iv.dterr)}</p>`:""}</div>`;
 if(n!=null&&n>=0)return `<div class="ivc ivdate"><b>📅 ${n===0?"Your interview is today":n===1?"Your interview is tomorrow":"Interview in "+n+" days"}</b><p>${esc(dFmt(s.date,{weekday:"short",day:"numeric",month:"short"}))}${s.post?" · "+esc(s.post):""}</p><p style="margin-top:6px"><button class="lnk" style="padding:0" onclick="iv.dt=true;iv.dterr='';ivHome()">Change</button> · <button class="lnk" style="padding:0" onclick="ivDateClear()">Remove</button></p></div>`;
 return `<button class="opt" onclick="iv.dt=true;iv.dterr='';ivHome()"><div class="row"><b>📅 Got an interview? Add the date</b><span>›</span></div><small style="color:var(--mute)">You'll get a countdown and a suggestion for each day.</small></button>`}
function ivDateSave(){const d=(document.getElementById("ivdt")||{}).value||"",p=((document.getElementById("ivpost")||{}).value||"").trim().slice(0,60);
 if(!/^\d{4}-\d{2}-\d{2}$/.test(d)){iv.dterr="Choose a date.";return ivHome()}if(daysTo(d)<0){iv.dterr="Choose today or a date in the future.";return ivHome()}
 const s=ivS();s.date=d;s.post=p;iv.dt=false;save();toast("Countdown added");ivHome()}
function ivDateClear(){const s=ivS();delete s.date;delete s.post;save();ivHome()}
function ivTip(){const s=ivS(),n=ivDays(),sr=IVX.stories.filter(x=>stReady(x.id)).length,pr=Object.keys(s.pr).length,today=isoD(new Date()),mockToday=s.mk.some(m=>m.iso===today),pd=Object.keys(s.prio).length;
 if(n===0)return ["Read your stories once, then stop revising. You're ready.","stories"];
 if(mockToday)return ["Mock done today. Rest, or read one of your stories.","stories"];
 if(n<=2)return [n===1?"One last short mock, then an early night.":"Run a mock interview today.","mock"];
 if(sr<4)return [(4-sr)+" more "+(4-sr===1?"story":"stories")+" to write","stories"];
 if(pr<10)return ["Practise 3 questions from the bank","bank"];
 if(!pd)return ["Try a prioritisation task","prio"];
 if(n<=7||!s.mk.length)return ["Try a mock interview today","mock"];
 return ["Practise 3 more questions","bank"]}
function ivCD(){if(!showIv())return "";const n=ivDays();if(n==null||n<0)return "";const t=ivTip(),s=ivS();
 return `<button class="nx ivcd" onclick="openIv();ivGo('${t[1]}')"><small>${n===0?"Interview today":n===1?"Interview tomorrow":"Interview in "+n+" days"}${s.post?" · "+esc(s.post):""}</small><b>${esc(t[0])}</b><span>Interview prep ›</span></button>`}

