async function hcFile(kind){const say=m=>{hc.msg=m;const e=document.getElementById("hcm");if(e)e.textContent=m};
 try{const dl=await claude.use("downloads");if(!dl)return say("Saving a file is not available here.");say("Preparing…");
  const b64=b=>new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(b)}),imgs={};
  if(kind==="html")for(const x of hcEv())if(x.f){const b=await phGet(x.f).catch(()=>null);if(b)imgs[x.f]=isPdf(x.f)?{name:b.name||""}:{src:await b64(b)}}
  const html=hcHtml(kind==="html",imgs),d=isoD(new Date());
  await dl.save(kind==="doc"?{filename:"hcpc-cpd-profile-"+d+".doc",data:new Blob(["\ufeff"+html],{type:"application/msword"})}:{filename:"hcpc-cpd-profile-"+d+".html",data:new Blob([html],{type:"text/html"})});
  S.cpdX=d;save();say("Saved.")}catch(e){say(e&&e.code==="declined"?"Not saved.":"Saving a file is not available here.")}}
async function hcPdfs(){const say=m=>{hc.msg=m;const e=document.getElementById("hcm");if(e)e.textContent=m};const P=hcEv().filter(x=>x.f&&isPdf(x.f));if(!P.length)return say("None of your chosen activities has a PDF attached.");
 try{const dl=await claude.use("downloads");if(!dl)return say("Saving a file is not available here.");let n=0;for(const x of P){const b=await phGet(x.f).catch(()=>null);if(!b)continue;await dl.save({filename:"evidence-"+x.n+"-"+String(b.name||"document.pdf").replace(/[^\w.\-]+/g,"-"),data:b});n++}say(n?"Saved "+n+" "+(n===1?"file":"files")+".":"Files not found on this device.")}catch(e){say(e&&e.code==="declined"?"Not saved.":"Saving a file is not available here.")}}

