 let s2=sum.charAt(0).toLowerCase()+sum.slice(1);if(gt==="c")s2=s2.replace(/type 2 respiratory failure/i,"type 2 picture (confirm hypoxaemia with SpO₂ and the oxygen they're on)");if(gt==="v")s2=s2.replace(/^respiratory/,"likely respiratory");
