function abCalc(){const v=ab.in,ty=abTy(v),sub=ABT[ty][2],inp=(k,l,u,st,ph)=>`<label class="abi"><span>${l}</span><input id="ab-${k}" class="cin" type="number" inputmode="decimal" step="${st}" value="${esc(v[k])}" placeholder="${ph}" oninput="ab.in.${k}=this.value"><small>${u}</small></label>`;
 return `<h1 style="font-size:1.5rem;margin:6px 0 2px">Step-through interpreter</h1><p class="tag" style="margin:0 0 10px">Enter the values from a gas, then work through it one step at a time.</p>`+
 `<label class="cfl">Type of sample</label><div class="seg" role="group" aria-label="Type of sample">${Object.entries(ABT).map(([k,t])=>`<button class="${ty===k?"on":""}" aria-pressed="${ty===k}" onclick="ab.in.ty='${k}';ab.err='';home()">${t[0]}</button>`).join("")}</div><p class="tag" style="margin:0 0 10px">${esc(ABT[ty][4])}</p>`+
 `<div class="abg2">${inp("ph","pH","","0.01","7.40")}${inp("co2",`P${sub}CO₂`,"kPa","0.1","5.3")}${inp("o2",`P${sub}O₂`,ty==="a"?"kPa":"kPa, optional","0.1","12")}${inp("hco3","HCO₃⁻","mmol/L","1","24")}${inp("be","Base excess","optional","1","0")}</div>`+
 `<label class="cfl" for="ab-fi">Oxygen at the time of the gas</label><select id="ab-fi" class="cin" onchange="const o=ABO[this.value];ab.in.fi=o[1];ab.in.fl=o[0]">${ABO.map((o,i)=>`<option value="${i}" ${v.fl===o[0]?"selected":""}>${esc(o[0])}</option>`).join("")}</select>`+
 (ab.err?`<div class="fb bad" style="margin-top:10px"><b>${esc(ab.err)}</b></div>`:"")+
 `<button class="go" style="margin-top:12px" onclick="abRun(false)">Step through it</button><button class="opt" style="text-align:center;margin-top:10px" onclick="abRun(true)">Just show me the interpretation</button>`+
 `<button class="lnk" style="width:100%;margin-top:6px" onclick="abRand()">Try a random practice gas</button>`}
function abRand(){const c=ABG.cases[Math.floor(Math.random()*ABG.cases.length)];abGo("calc",{in:{ty:"a",ph:c.v.ph,co2:c.v.co2,o2:c.v.o2,hco3:c.v.hco3,be:c.v.be??"",fi:c.fio2,fl:(ABO.find(o=>o[1]===c.fio2)||["Room air"])[0]}})}
function abRun(show){const v=ab.in,n=k=>v[k]===""||v[k]==null?NaN:+v[k];
 const ty=abTy(v),sub=ABT[ty][2];const bad=[["ph",6.8,7.8,"pH"],["co2",1,20,`P${sub}CO₂`],["o2",1,80,`P${sub}O₂`],["hco3",5,60,"HCO₃⁻"]].find(([k,lo,hi])=>!(k==="o2"&&ty!=="a"&&isNaN(n(k)))&&!(n(k)>=lo&&n(k)<=hi));
 if(bad){ab.err=`Check the ${bad[3]}: it should be between ${bad[1]} and ${bad[2]}${bad[0]==="co2"||bad[0]==="o2"?" kPa":""}.`;return home()}
 ab.err="";const r=abEval(v);abGo("step",{st:r,i:show?r.st.length:0,pk:[],show,cs:null})}
function abCaseGo(id){const c=ABG.cases.find(x=>x.id===id);ab.in={ty:c.ty||"a",ph:c.v.ph,co2:c.v.co2,o2:c.v.o2,hco3:c.v.hco3,be:c.v.be??"",fi:c.fio2,fl:c.o2};const r=abEval(ab.in);abGo("step",{st:r,i:0,pk:[],show:false,cs:id})}
const abFlag=(x,lo,hi)=>x<lo?" alo":x>hi?" ahi":"";
function abGasCard(){const v=ab.in,c=ab.cs&&ABG.cases.find(x=>x.id===ab.cs),ty=abTy(v),sub=ABT[ty][2],no2=v.o2===""||v.o2==null;
 return (c?`<h1 style="font-size:1.35rem;margin:6px 0 4px">${esc(c.n)}</h1><p style="margin:0 0 8px">${esc(c.ctx)}</p>`:"")+
 `<div class="abgv"><div class="${abFlag(+v.ph,7.35,7.45)}"><small>pH</small><b>${v.ph}</b></div><div class="${abFlag(+v.co2,4.7,6)}"><small>P${sub}CO₂</small><b>${v.co2}</b></div><div class="${ty==="a"?abFlag(+v.o2,10,999):""}"><small>P${sub}O₂</small><b>${no2?"–":v.o2}</b></div><div class="${abFlag(+v.hco3,22,26)}"><small>HCO₃⁻</small><b>${v.hco3}</b></div>${v.be!==""&&v.be!=null?`<div class="${abFlag(+v.be,-2,2)}"><small>BE</small><b>${v.be}</b></div>`:""}</div><p class="tag" style="margin:4px 0 10px">${ABT[ty][0]} · ${esc(c?c.o2:v.fl)}</p>`}
function abStep(){const R=ab.st;if(!R)return abCalc();const st=R.st,i=ab.i;let o=abGasCard();
 o+=st.slice(0,i).map((s,k)=>`<div class="abd${ab.show||ab.pk[k]===s.a?"":" x"}"><b>${esc(s.o[s.a])}</b><small>${esc(s.why)}</small></div>`).join("");
 if(i<st.length){const s=st[i],pk=ab.pk[i];
  o+=`<div class="sec">Step ${i+1} of ${st.length}</div><h2 class="ivq" style="font-size:1.15rem">${esc(s.q)}</h2>`+s.o.map((x,k)=>`<button class="opt ${pk!=null?(k===s.a?"ok":k===pk?"bad":""):""}" ${pk!=null?"disabled":""} onclick="abPick(${k})">${esc(x)}</button>`).join("")+
  (pk!=null?`<div class="fb ${pk===s.a?"ok":"bad"}"><b>${pk===s.a?"Right":"Not quite"}</b>${esc(s.why)}</div><button class="go" onclick="ab.i++;home()">Continue</button>`:"");
  return o}
 const sc=ab.show?null:st.filter((s,k)=>ab.pk[k]===s.a).length,c=ab.cs&&ABG.cases.find(x=>x.id===ab.cs),fp=ABG.flow.problems.find(p=>p.id===(c?c.flow:R.fl));
 o+=`<div class="abs"><small>Interpretation</small><b>${esc(c?c.sum:R.sum)}</b>${sc!=null?`<span>${sc} of ${st.length} steps right first time</span>`:""}</div>`;
 if(c)o+=`<div class="sec">Likely cause</div><p>${esc(c.cause)}</p><div class="sec">Is it physio amenable? ${amBd(c.am)}</div><p>${esc(c.physio)}</p><div class="sec">Reasoning prompts</div>`+ivUl(c.act);
 if(fp)o+=`<button class="opt" onclick="abGo('fdet',{fl:'${fp.id}'})"><b>🧭 ${esc(fp.n)}</b><br><small style="color:var(--mute)">Causes, what's physio amenable and when to escalate ›</small></button>`;
 o+=`<div class="tabs" style="margin-top:6px">${c?`<button class="opt" style="text-align:center" onclick="abNextCase()">Next case</button>`:`<button class="opt" style="text-align:center" onclick="abGo('calc')">Another gas</button>`}</div>`;
 return o}
function abPick(k){const i=ab.i,s=ab.st.st[i];if(ab.pk[i]!=null)return;ab.pk[i]=k;if(k===s.a)sfx("ok",i);else sfx("bad");
 if(i===ab.st.st.length-1&&ab.cs){const sc=ab.st.st.filter((x,j)=>ab.pk[j]===x.a).length,d=abS().done;if(!d[ab.cs]){S.xpT=(S.xpT||0)+10}d[ab.cs]=Math.max(d[ab.cs]||0,sc);save()}home()}
function abNextCase(){const d=abS().done,i=ABG.cases.findIndex(x=>x.id===ab.cs),nx=ABG.cases.slice(i+1).concat(ABG.cases.slice(0,i+1)).find(x=>!d[x.id])||ABG.cases[(i+1)%ABG.cases.length];abCaseGo(nx.id)}
function abCases(){const d=abS().done;
 return `<h1 style="font-size:1.5rem;margin:6px 0 2px">Worked cases</h1><p class="tag" style="margin:0 0 10px">Each case gives you a patient and a gas. Interpret it, then think about the cause and whether physio can help.</p>`+
 ABG.cases.map(c=>`<button class="opt" onclick="abCaseGo('${c.id}')"><div class="row"><b>${c.ty&&c.ty!=="a"?`<span class="tag" style="margin-right:6px">${ABT[c.ty][0]}</span>`:""}${esc(c.n)}</b><span>${d[c.id]!=null?"✅":""}</span></div><small style="color:var(--mute)">${esc(c.o2)}</small></button>`).join("")}
function abFlow(){return `<h1 style="font-size:1.5rem;margin:6px 0 2px">What's physio amenable?</h1><p class="tag" style="margin:0 0 8px">${esc(ABG.flow.note)}</p><div class="abfl"><span>Gas</span>›<span>Problem</span>›<span>Cause</span>›<span>Physio amenable?</span></div>`+
 ABG.flow.problems.map(p=>`<button class="opt" onclick="abGo('fdet',{fl:'${p.id}'})"><div class="row"><b>${esc(p.n)}</b><span>›</span></div><small style="color:var(--mute)">${esc(p.gas)}</small></button>`).join("")+`<div class="sec">Always</div>`+ivUl(ABG.flow.always)}
function abFDet(){const p=ABG.flow.problems.find(x=>x.id===ab.fl);if(!p)return abFlow();
 return `<h1 style="font-size:1.45rem;margin:6px 0 2px">${esc(p.n)}</h1><p class="tag" style="margin:0 0 10px">${esc(p.gas)}</p><div class="orf"><b>Escalate now if</b><ul>${p.esc.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div><div class="sec">What's causing it?</div>`+
 p.causes.map(c=>`<details class="abca"><summary><b>${esc(c.n)}</b>${amBd(c.am)}</summary><p>${esc(c.why)}</p>${c.opts&&c.opts.length?`<small class="abh">${c.am==="no"?"Who manages it":"Options to consider, within your competence and local policy"}</small>`+ivUl(c.opts):""}${c.caut&&c.caut.length?`<small class="abh" style="color:var(--bad)">Cautions</small>`+ivUl(c.caut):""}</details>`).join("")}

