 /* ---------- v278: muscle cards zoom the engraving to the highlighted muscle ---------- */
 function msCrop(){document.querySelectorAll(".clvw").forEach(w=>{try{
  if(!w.parentNode||!w.parentNode.querySelector(":scope > dl.mst"))return;
  const v=w.querySelector(".clvv"),sv=v&&v.querySelector("svg.sfig");if(!sv||sv.dataset.full)return;
  const hl=[...sv.querySelectorAll("g.hl")];if(!hl.length)return;
  const vb=sv.getAttribute("viewBox").split(/[ ,]+/).map(Number);let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;
  hl.forEach(g=>{const cp=(g.getAttribute("clip-path")||"").match(/#([^)]+)/),ce=cp&&sv.querySelector("#"+CSS.escape(cp[1])),r=(ce&&ce.firstElementChild||g).getBBox();
   if(r.width){x0=Math.min(x0,r.x);y0=Math.min(y0,r.y);x1=Math.max(x1,r.x+r.width);y1=Math.max(y1,r.y+r.height)}});
  if(x1<=x0)return; // not laid out yet
  const m=Math.max(x1-x0,y1-y0)*.18+12;x0-=m;y0-=m;x1+=m;y1+=m;
  const A=358/300;let ww=x1-x0,hh=y1-y0;if(ww/hh<A){const nw=hh*A;x0-=(nw-ww)/2;ww=nw}else{const nh=ww/A;y0-=(nh-hh)/2;hh=nh}
  if(ww>vb[2]){ww=vb[2];x0=vb[0]}if(hh>vb[3]){hh=vb[3];y0=vb[1]}
  x0=Math.max(vb[0],Math.min(x0,vb[0]+vb[2]-ww));y0=Math.max(vb[1],Math.min(y0,vb[1]+vb[3]-hh));
  sv.dataset.full=vb.join(" ");
  if(hh/ww>vb[3]/vb[2]*.85)return; // the muscle fills most of the picture (trapezius): leave it whole
  const crop=[x0,y0,ww,hh].map(n=>n.toFixed(1)).join(" ");sv.dataset.crop=crop;sv.setAttribute("viewBox",crop);
  v.insertAdjacentHTML("beforeend",`<button class="lnk mswh" onclick="msWhole(this)">⤢ Show whole picture</button>`);
 }catch(e){}})}
 function msWhole(b){try{const sv=b.closest(".clvv").querySelector("svg.sfig"),z=sv.getAttribute("viewBox")===sv.dataset.crop;sv.setAttribute("viewBox",z?sv.dataset.full:sv.dataset.crop);b.textContent=z?"⤡ Zoom to the muscle":"⤢ Show whole picture"}catch(e){}}
 window.msCrop=msCrop;window.msWhole=msWhole;
 try{new MutationObserver(()=>{if(document.querySelector(".clvw svg.sfig:not([data-full])"))msCrop()}).observe(document.documentElement,{childList:true,subtree:true})}catch(e){}

