 /* ---------- v282: tester version: report a problem, feedback, welcome note ---------- */
 const RP_VER="v521";let rpCtx=null,rpCat=null;
 function rpBtn(kind,id,i){return `<button class="rpb" onclick="rpOpen('${kind}','${id}',${i})">⚑ Report a problem with this card</button>`}
 function rpCtxFor(kind,id,i){try{
  if(kind==="c"){const c=LEARN[id][i],cd=typeof COND!=="undefined"&&COND.find(x=>x.id===id);return {kind:"card",layer:id,card:i,title:c.t,where:(cd?"Condition: "+cd.n:(typeof tn==="function"?tn(id):id))+" · card "+(i+1)+": "+c.t}}
  if(kind==="q"){const q=window._curQ||(queue&&queue[0]);if(!q)return {kind:"question",where:"A question"};const b=q.base||q;return {kind:"question",qid:b.id||"",layer:b.l||"",card:b.c,stem:String(q.q||"").slice(0,300),answer:String((q.o||[])[q.a]||"").slice(0,120),where:"Question: "+String(q.q||"").slice(0,90)}}
 }catch(e){}return {kind:"general",where:"The app in general"}}
 function rpOpen(kind,id,i){rpCtx=rpCtxFor(kind,id,i);rpCat=null;const cats=kind==="g"?["Something I liked","Something confusing","Something broken","An idea"]:["Wrong or inaccurate","Unclear wording","Figure problem","Something broken","Other"];
  const d=document.createElement("div");d.className="rpov";d.id="rpov";d.setAttribute("role","dialog");d.setAttribute("aria-modal","true");d.setAttribute("aria-label",kind==="g"?"Message Phyzly":"Report a problem");
  d.innerHTML=`<div class="rpsh"><h2>${kind==="g"?"Message Phyzly":"Report a problem"}</h2><p class="rpctx"></p><div class="rpch">${cats.map(c=>`<button type="button" aria-pressed="false" onclick="rpPick(this)">${c}</button>`).join("")}</div><label for="rptx">${kind==="g"?"Tell us what you think":"What's the problem?"}</label><textarea id="rptx" placeholder="${kind==="g"?"Anything goes: what worked, what didn't, what you'd change":"For example: the answer should be C6, not C5"}"></textarea><p class="tag" id="rpmsg" style="margin:8px 0 0"></p><div class="tabs" style="margin-top:12px"><button class="opt" style="text-align:center" onclick="rpClose()">Cancel</button><button class="go" id="rpgo" onclick="rpSend()">Send</button></div></div>`;
  d.querySelector(".rpctx").textContent=rpCtx.where;d.addEventListener("click",e=>{if(e.target===d)rpClose()});document.body.appendChild(d);setTimeout(()=>{try{document.getElementById("rptx").focus()}catch(e){}},50)}
 function rpPick(b){b.parentNode.querySelectorAll("button").forEach(x=>x.setAttribute("aria-pressed","false"));b.setAttribute("aria-pressed","true");rpCat=b.textContent}
 function rpClose(){const d=document.getElementById("rpov");if(d)d.remove()}
 async function rpSend(){const tx=(document.getElementById("rptx").value||"").trim(),msg=document.getElementById("rpmsg"),go=document.getElementById("rpgo");
  if(!tx&&!rpCat){msg.textContent="Choose a type or write a note first.";return}
  go.disabled=true;msg.textContent="Sending…";
  const row=Object.assign({},rpCtx,{cat:rpCat||"",text:tx.slice(0,2000),ts:Date.now(),ver:RP_VER,ua:navigator.userAgent.slice(0,120)});
  try{if(typeof claude==="undefined"||!claude.use)throw 0;const [db,user]=await Promise.all([claude.use("db"),claude.use("user")]);if(!db||!user)throw 0;const uid=await user.id();if(!uid)throw 0;
   await db.collection("feedback/"+uid+"/reports").add(row);try{await db.doc("feedback/"+uid).set({last:Date.now()})}catch(e){}msg.textContent="Thanks, that's been sent.";setTimeout(rpClose,900);try{toast("Thanks for the report")}catch(e){}}
  catch(e){try{const k="rpq",q=JSON.parse(localStorage.getItem(k)||"[]");q.push(row);localStorage.setItem(k,JSON.stringify(q))}catch(er){}
   msg.textContent="It couldn't be sent from here, so please take a screenshot and send it to Oliver.";go.disabled=false}}
 window.rpBtn=rpBtn;window.rpOpen=rpOpen;window.rpPick=rpPick;window.rpClose=rpClose;window.rpSend=rpSend;
 /* report link under the answer feedback after every question */
 try{new MutationObserver(()=>{const fb=document.getElementById("fb");if(fb&&fb.textContent.trim()&&!fb.querySelector(".rpb")&&typeof queue!=="undefined"&&queue&&queue[0]){const b=document.createElement("button");b.className="rpb";b.textContent="⚑ Report a problem with this question";b.onclick=()=>rpOpen("q");fb.appendChild(b)}}).observe(document.documentElement,{childList:true,subtree:true})}catch(e){}
 /* one-time welcome note for testers */
 function twShow(){try{if(S.tw3||S.obFlow||document.getElementById("twov"))return;if(!S.role)return;const d=document.createElement("div");d.className="twov";d.id="twov";d.setAttribute("role","dialog");d.setAttribute("aria-modal","true");d.setAttribute("aria-label","Welcome, tester");
  d.innerHTML=`<div class="twbx"><h2>Thanks for testing Phyzly</h2><p style="margin:0">This is an early version. The content is a draft and has not yet been checked by a specialist clinician, so please don't rely on it for practice.</p><p style="margin:10px 0 0"><b>Please test:</b></p><ul><li><b>Foundations</b> and the <b>Shoulder</b> (in Anatomy)</li><li>anything else that's open, if you have time</li></ul><p style="margin:0 0 6px">Spot something wrong or unclear? Tap <b>⚑ Report a problem</b> under any card or answer. For anything else, tap <b>💬</b> at the top of the home screen. Reports are sent with your name.</p><p style="margin:0 0 10px;padding:8px 10px;border-radius:10px;background:var(--bg);font-size:.9rem"><b>Confidential.</b> Phyzly, its content and design are © Oliver Jones 2026. Please don't copy, duplicate, remix, screenshot to share, or pass on the link or any part of the app.</p><button class="go" onclick="S.tw2=1;S.tw3=1;save();document.getElementById('twov').remove();window.obTourGo&&obTourGo()">I agree, start testing</button></div>`;
  document.body.appendChild(d)}catch(e){}}
 window.twShow=twShow;
 try{const f=()=>{if(!document.querySelector(".cfoot")){const d=document.createElement("div");d.className="cfoot";d.setAttribute("role","note");d.textContent="© Oliver Jones 2026 · Confidential · Do not copy or share";document.body.appendChild(d)}};if(document.body)f();else document.addEventListener("DOMContentLoaded",f)}catch(e){}

