 /* ---------- v308: hide the floating bar while scrolling down, bring it back on scroll up ---------- */
 try{
  let lastY=window.scrollY,acc=0,tick=false;
  const navEl=()=>document.getElementById("nav");
  const mustShow=()=>{const h=document.documentElement,maxY=h.scrollHeight-window.innerHeight;
   return window.scrollY<40||maxY<80||window.scrollY>maxY-24||!!document.querySelector(".sheet,.ifbg,.phv,.achov,.cpc,.lvc,.stkov")};
  window.navReveal=function(){const n=navEl();if(n)n.classList.remove("hid");document.body.classList.remove("navhid");acc=0};
  const onScroll=()=>{tick=false;const n=navEl();if(!n||!n.classList.contains("show"))return;const y=window.scrollY,d=y-lastY;lastY=y;
   if(mustShow()){n.classList.remove("hid");document.body.classList.remove("navhid");acc=0;return}
   if((d>0&&acc<0)||(d<0&&acc>0))acc=0;acc+=d;
   if(acc>28)n.classList.add("hid");else if(acc<-14)n.classList.remove("hid");document.body.classList.toggle("navhid",n.classList.contains("hid"))};
  window.addEventListener("scroll",()=>{if(!tick){tick=true;requestAnimationFrame(onScroll)}},{passive:true});
  /* a new screen always starts with the bar showing */
  try{new MutationObserver(()=>{lastY=window.scrollY;navReveal()}).observe(document.getElementById("app"),{childList:true})}catch(e){}
  /* keep the floating gap when the phone's viewport is pinned by hand */
  const gapFix=()=>{try{const n=navEl();if(n&&n.style.top&&!n.dataset.g){n.style.top=(parseFloat(n.style.top)-10)+"px"}}catch(e){}};
  try{if(window.visualViewport){visualViewport.addEventListener("resize",gapFix);visualViewport.addEventListener("scroll",gapFix)}window.addEventListener("resize",gapFix);setTimeout(gapFix,20);setTimeout(gapFix,620)}catch(e){}
 }catch(e){console.error("v308",e)}

