   const labs=Object.entries(P).map(([k,p])=>{const i=I[k];return `<button class="k2lab ${p[2]==="L"?"r":""} ${i.st} ${i.next?"next":""} ${sel===k?"sel":""}" style="left:${(p[3]/380*100).toFixed(2)}%;top:${(p[4]/720*100).toFixed(2)}%" onclick="selBody('${k}')" aria-hidden="true" tabindex="-1"><b>${K2L[k]}</b><small>${sm(i)}</small></button>`}).join("");
