   if(!i.live)return h+`<p style="margin:8px 0 0;color:var(--mute)">Being written to the same template: six layers, Palpate guides, a mastery check and a viva.</p></div>`;
   h+=`<div class="k2tl"><div><b>${i.fresh==null?"–":i.fresh+"%"}</b><span>fresh</span></div><div><b>${i.due}</b><span>due</span></div><div><b>${i.pl?i.pd+"/"+i.pl:"–"}</b><span>palpate</span></div><div><b>${i.mast?(i.best?i.best+"%":"✓"):i.lay>=i.n?"Ready":"🔒"}</b><span>${i.mast?"mastered":"mastery"}</span></div></div>`;
   const nx=i.G.ls.findIndex(l=>!(S.learn||{})[l]);
   if(i.mast)h+=i.due?`<button class="go k2go" style="margin:0" onclick="rfRun(RGL['${i.id}'].ls,'${esc(i.r.n)}')">Refresh ${i.due} due<small>Keep it fresh</small></button><button class="k2go2" onclick="openRegion('${i.id}')">Open the path</button>`:`<button class="go k2go" style="margin:0" onclick="openRegion('${i.id}')">Open the path<small>Nothing due. Nice work.</small></button>`;
