   if(x.k==="sec")return `<div class="gsr"><button class="gsm" onclick="gsGo(${esc(JSON.stringify(x.go))})"><b>${x.ic?x.ic+" ":""}${esc(x.t)}</b>${sub}</button><button class="gsq" onclick='gsRefresh(${JSON.stringify(x.ids)})' aria-label="Quick refresh: ${esc(x.t)}">⚡ Refresh</button></div>`;
   if(x.k==="card")return `<div class="gsr"><button class="gsm" onclick="gsCard('${x.l}',${x.i})"><b>${esc(x.t)}</b>${sub}</button><button class="gsq" onclick="gsRefresh(['${x.l}'],${x.i})" aria-label="Quick refresh: ${esc(x.t)}">⚡ Refresh</button></div>`;
