  const nice=e=>{const m=(e&&(e.message||e.error_description))||String(e||"");if(/rate limit|too many/i.test(m))return "Too many tries. Wait a minute, then try again.";if(/expired|invalid/i.test(m)&&/otp|token|code/i.test(m))return "That code didn't work or has expired. Check it, or send a new one.";if(/network|fetch|Failed to fetch|Load failed/i.test(m))return "No connection. Check your signal and try again.";return m||"Something went wrong. Try again."};
