  const FORCED=window.PZ_ONLY==="portfolio"?new Set(["ivTools","plcTools","appTools"]):new Set();
  const stalePre=(f,v)=>f==="preTools"&&window.PZ_ONLY==="portfolio"&&!v.pre466;
