    let pr=profRow(),ph=hsh(pr);if(sy.prof!==ph&&S.role){if(S.acct&&!S.acct.newsCh){const q=await sb.from("profiles").select("marketing_opt_in,marketing_opt_in_at").eq("id",uid).maybeSingle();live();if(q.error)throw q.error;if(q.data&&q.data.marketing_opt_in!=null){S.acct.news=!!q.data.marketing_opt_in;S.acct.newsAt=q.data.marketing_opt_in?(q.data.marketing_opt_in_at||new Date().toISOString()):null;pr=profRow();ph=hsh(pr)}}const {error}=await sb.from("profiles").update(pr).eq("id",uid);live();if(error)throw error;sy.prof=ph;if(S.acct&&S.acct.newsCh){delete S.acct.newsCh;save()}}
    /* 3. photos: upload new, remove ones no longer used */
