    /* a photo that isn't on this device (made on another one, not yet viewed here) has nothing to upload */
    for(const id of want){if(sy.ph[id])continue;let b=null;try{b=await phGet(id)}catch(e){}live();if(!b){sy.ph[id]=1;continue}
     const path=phPath(id),mime=id.startsWith("pd")?"application/pdf":"image/jpeg";
     const u=await sb.storage.from("evidence").upload(path,b,{contentType:mime,upsert:true});live();if(u.error)throw u.error;
     const r=await sb.from("evidence").upsert({user_id:uid,id,entry_id:null,path,mime,bytes:Math.max(1,b.size||1),deleted_at:null},{onConflict:"user_id,id"});live();if(r.error)throw r.error;sy.ph[id]=1}
    const drop=Object.keys(sy.ph).filter(id=>!want.has(id));
    if(drop.length){const rm=await sb.storage.from("evidence").remove(drop.map(phPath));live();if(rm&&rm.error)throw rm.error;const mk=await sb.from("evidence").update({deleted_at:new Date().toISOString()}).eq("user_id",uid).in("id",drop);live();if(mk&&mk.error)throw mk.error;drop.forEach(id=>delete sy.ph[id])}
    /* 4. pull what changed elsewhere: entries in pages of 1,000 with their own bookmark, saved items with theirs (R10) */
