const QBY={};Object.values(B).forEach(v=>v.forEach(q=>{QBY[q.id]=q;if(q.alt)QBY[q.alt.id]=q.alt}));
const pickForm=q=>{const m=S.miss&&S.miss[q.id];return m&&q.alt&&(m.ok||0)%2===1?q.alt:q};
