const nrm=s=>String(s).toLowerCase().replace(/'/g,"").replace(/\(([^)]*)\)/g," $1 ").replace(/[^a-z0-9 ]/g," ").replace(/\b(the|of|a|an|and)\b/g," ").replace(/\s+/g," ").trim().split(" ").map(w=>w.length>3?w.replace(/(sses|xes)$/,m=>m.slice(0,-2)).replace(/s$/,""):w).join(" ");
function accepts(nm){const b=[nm,nm.replace(/\s*\([^)]*\)/g,"")],m=nm.match(/\(([^)]*)\)/);if(m&&!/\b(?:C[1-8]|T1[0-2]|T[1-9]|L[1-5]|S[1-5])\b|\bCN [IVX]+\d?\b/.test(m[1]))b.push(m[1]);const gw=b[1].replace(/\s+(nerve|muscle|joint|ligament|bone|artery)s?$/i,"");if(gw!==b[1]&&gw.length>=4)b.push(gw);(ALIAS[nm.toLowerCase()]||[]).forEach(a=>b.push(a));try{const lo=nm.toLowerCase(),ln=nrm(nm);Object.keys(ALIAS).forEach(k=>{const v=ALIAS[k]||[];if(v.some(x=>x===lo||nrm(x)===ln)){b.push(k);v.forEach(x=>b.push(x))}})}catch(e){}return [...new Set(b.map(nrm))].filter(Boolean)}
