  SO.ro=(await US.can("data.write"))===false;
  const me=await DB.doc("players/"+uid).get();if(me.exists)ME=Object.assign({},me.data());
  SO.st="on";const eh=()=>{};try{fb.own=!!(await US.isOwner())}catch(e){}fbFlush();
  DB.collection("players").onSnapshot(s=>{PL={};s.docs.forEach(d=>PL[d.id]=d.data());refreshSoc()},eh);DB.collection("feed").onSnapshot(s=>{FEED={};s.docs.forEach(d=>FEED[d.id]=d.data());fvNotify();if(tab==="friends"&&fview==="feed")feedRender()},eh);DB.collection("fives").onSnapshot(s=>{FIV={};s.docs.forEach(d=>FIV[d.id]=d.data());fvNotify();if(tab==="friends"&&fview==="feed")feedRender()},eh);
  DB.collection("links").where("p","array-contains",uid).onSnapshot(s=>{LK=s.docs.map(d=>Object.assign({id:d.id},d.data()));refreshSoc()},eh);
  DB.collection("matches").where("p","array-contains",uid).onSnapshot(s=>{MT=s.docs.map(d=>Object.assign({id:d.id},d.data()));refreshSoc()},eh);
  if(ME)syncMe();
