/* ---------- v460: exports. PDF (jsPDF, with photos and attached PDFs), Excel (.xlsx written here), CSV and text.
   Files are delivered by the share sheet on phones (Save to Files, WhatsApp, email) or a normal download on computers;
   inside the Claude app the downloads capability is used instead. Exports are plain and unbranded. ---------- */
const XP={ready:null,busy:false,msg:""};
const xpLocal=()=>window.PZ_ONLY==="portfolio";
const xpJs={};
function xpLoad(src){return xpJs[src]||(xpJs[src]=new Promise((res,rej)=>{const s=document.createElement("script");s.src=src;s.onload=()=>res();s.onerror=()=>{delete xpJs[src];rej(new Error("Couldn't load "+src))};document.head.appendChild(s)}))}
async function xpJsPDF(){if(!(window.jspdf&&window.jspdf.jsPDF))await xpLoad(xpLocal()?"/vendor/jspdf-4.2.1.umd.min.js":"https://cdn.jsdelivr.net/npm/jspdf@4.2.1/dist/jspdf.umd.min.js");return window.jspdf.jsPDF}
async function xpPdfLib(){if(!window.PDFLib)await xpLoad(xpLocal()?"/vendor/pdf-lib-1.17.1.min.js":"https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js");return window.PDFLib}
const xpB64=b=>new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(String(fr.result).split(",")[1]);fr.onerror=()=>rej(fr.error);fr.readAsDataURL(b)});
let xpFontData=null;
async function xpFonts(doc){if(!xpLocal())return false;
 if(!xpFontData)xpFontData=(async()=>{const get=async f=>{const r=await fetch("/vendor/"+f);if(!r.ok)throw new Error("font");return xpB64(await r.blob())};return {r:await get("Inter-Regular.ttf"),b:await get("Inter-SemiBold.ttf"),i:await get("Inter-Italic.ttf")}})().catch(e=>{xpFontData=null;throw e});
 const F=await xpFontData;doc.addFileToVFS("Inter-Regular.ttf",F.r);doc.addFont("Inter-Regular.ttf","Inter","normal");doc.addFileToVFS("Inter-SemiBold.ttf",F.b);doc.addFont("Inter-SemiBold.ttf","Inter","bold");doc.addFileToVFS("Inter-Italic.ttf",F.i);doc.addFont("Inter-Italic.ttf","Inter","italic");return true}
/* the built-in PDF font only has Western European characters */
