  say(doc.numPages+(doc.numPages===1?" page":" pages"));const W=Math.min(body.clientWidth-24,820),dpr=Math.min(2,window.devicePixelRatio||1),done={};
  const first=await doc.getPage(1),v1=first.getViewport({scale:1}),H=Math.round(W*v1.height/v1.width);
