function hcSlug(t){return String(t||"").toLowerCase().replace(/^(reflective record|photo|document)(: | from )/,"$1-").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,48)||"evidence"}
function hcGoEv(){const ev=hcEv();if(!ev.length)return xpSay("Choose some activities first.");
 xpRun("files",async()=>{const out=[];for(const x of ev){const base="evidence-"+x.n+"-"+hcSlug(x.d);
   if(x.f&&isPdf(x.f)){const b=await xpBlob(x.f);if(b)out.push({name:base+".pdf",blob:b});continue}
   if(x.f){const b=await xpBlob(x.f);if(!b)continue}
   out.push({name:base+".pdf",blob:await xpPdf(async L=>{await hcEvPage(L,x,true)},hcFoot(x.n))})}
  if(!out.length)xpSay("Files not found on this device.");return out},"hc")}
