 G.fb=A(G.fb).filter(f=>f&&typeof f==="object"&&okid(f.id)).slice(0,400);
 G.fb.forEach(f=>{f.id=String(f.id);if(!day(f.d))f.d=today;f.who=str(f.who,80);f.rel=GRR.some(r=>r[0]===f.rel)?f.rel:"oth";f.ctx=str(f.ctx,80);f.txt=str(f.txt,3000);delete f.v;delete f.nm;delete f.rq;f.ph=A(f.ph).filter(i=>/^(ph|pd)[a-z0-9]{6,40}$/.test(String(i))).slice(0,12)});
