 G.sn=A(G.sn).filter(x=>x&&typeof x==="object"&&okid(x.id)).slice(0,24);
 G.sn.forEach(x=>{x.id=String(x.id);if(!day(x.d))x.d=today;x.n=str(x.n,80);x.it=A(x.it).filter(i=>i&&typeof i==="object").slice(0,200).map(i=>({q:GRQ.some(q=>q[0]===i.q)?i.q:"s",t:str(i.t,200),pil:GRPL.some(p=>p[0]===i.pil)?i.pil:"",ev:Math.max(0,Math.min(20,Math.round(+i.ev||0)))}))});
