 G.rq.forEach(x=>{x.id=String(x.id);x.who=str(x.who,60);x.fn=str(x.fn,40);x.ctx=str(x.ctx,80);if(!day(x.d))x.d=today;if(!day(x.x))x.x=x.d;delete x.tk;delete x.token});
 G.gone=A(G.gone).filter(okid).map(String).slice(-200);G.seen=A(G.seen).filter(okid).map(String).slice(-100);
