function grFbDel(){const f=grf;if(!f.del){f.del=true;if(armTap(/^Delete feedback$/,"Yes, delete"))return;return home()}const G=grS();(f.ph||[]).concat(f.phGone||[]).forEach(id=>{try{phDel(id).catch(()=>{})}catch(e){}});
 G.fb=G.fb.filter(x=>x.id!==f.id);G.sw.forEach(x=>{x.ev=x.ev.filter(e=>!(e.k==="fb"&&e.id===f.id))});save();grf=null;gv={v:"home",tab:"fb"};home();window.scrollTo(0,0)}

