/* ---------- v488: Use in my SWOC ----------
   One piece of feedback, or one CPD entry, can make several SWOC points and back up points already there.
   grf={k:"use",src:{k:"fb"|"cpd",id},pts:[{q,t,pil,n}],lk:{[swId]:{on,n}},keepCf,err}
   Each evidence link can carry a short note (n) of what in the source backs that point up. */
const GRU_MAX=10;
function grUseSrc(src,keep){
 if(src.k==="fb"){const f=grFbAll().find(x=>x.id===src.id);if(!f)return null;
  const parts=f.v?[["What you do well",f.w,"s"],["What to work on",f.k,"w"],["Anything else",f.o,"s"]].filter(p=>String(p[1]||"").trim()):(String(f.txt||"").trim()?[["What they said",f.txt,"s"]]:[]);
  return {t:"Feedback from "+grWho(f),s:[dFmt(f.d),grRn(f.rel),f.ctx].filter(Boolean).join(" · "),parts,sent:!!f.v}}
 const e=keep&&keep.id===src.id?keep:(typeof cpdAll==="function"?cpdAll():(S.cpd||[])).find(x=>x&&x.id===src.id);if(!e)return null;
 const parts=fwOf(e).f.map(x=>[x[1],e.r&&e.r[x[0]],"s"]).filter(p=>String(p[1]||"").trim());
 return {t:e.t||"CPD entry",s:dFmt(e.d)+" · CPD entry",parts}}
function grUse(k,id,keep){const G=grS(),lk={};
 G.sw.forEach(x=>{const e=x.ev.find(e=>e.k===k&&e.id===id);if(e)lk[x.id]={on:true,n:e.n||""}});
 const lg={};(G.gl||[]).forEach(g=>{const e=g.ev.find(e=>e.k===k&&e.id===id);if(e)lg[g.id]={on:true,n:e.n||""}});
 const src=grUseSrc({k,id},keep),q0=src&&src.parts[0]?src.parts[0][2]:"s";
 grf={k:"use",from:(grf&&grf.k==="fb")?"form":(gv&&gv.v==="fbv")?"fbv":(k==="fb"&&pf==="gr")?"log":"",src:{k,id},pts:[{q:q0,t:"",pil:"",n:""}],lk,lg,keepCf:keep||null,err:""};gv.just=null;tab="cpd";pf="gr";home();window.scrollTo(0,0)}
