/* ---------- v500: merging saved groups between devices ---------- */
/* mg3(base, mine, theirs): base is what both devices last agreed on. Objects merge key by key; lists of items with an id
   merge item by item (new items on either side are kept; an item deleted on one side goes, unless the other side edited
   it since, then the edit is kept); lists of plain values merge as sets; anything else: if only one side changed it,
   that change is taken; if both did, this device's wins. Nothing here talks to the network. */
function mgCl(v){try{return v==null?v:JSON.parse(JSON.stringify(v))}catch(e){return v}}
function mgEq(a,b){if(a===b)return true;try{return JSON.stringify(a)===JSON.stringify(b)}catch(e){return false}}
const mgObj=x=>!!x&&typeof x==="object"&&!Array.isArray(x);
const mgIdd=a=>Array.isArray(a)&&a.length>0&&a.every(x=>mgObj(x)&&(typeof x.id==="string"||typeof x.id==="number"));
const mgPrim=a=>Array.isArray(a)&&a.every(x=>x==null||typeof x!=="object");
function mg3(b,l,r){
 if(mgEq(l,r))return mgCl(l);
 if(b!==undefined&&mgEq(b,l))return mgCl(r);
 if(b!==undefined&&mgEq(b,r))return mgCl(l);
 if(mgObj(l)&&mgObj(r)){const B=mgObj(b)?b:{},o={},ks=new Set(Object.keys(l).concat(Object.keys(r)));
  ks.forEach(k=>{const inL=Object.prototype.hasOwnProperty.call(l,k),inR=Object.prototype.hasOwnProperty.call(r,k),inB=Object.prototype.hasOwnProperty.call(B,k);
   if(inL&&inR){o[k]=mg3(inB?B[k]:undefined,l[k],r[k]);return}
   if(inL){if(inB&&mgEq(B[k],l[k]))return;o[k]=mgCl(l[k]);return}
   if(inB&&mgEq(B[k],r[k]))return;o[k]=mgCl(r[k])});
  return o}
 if(Array.isArray(l)&&Array.isArray(r)){const Ba=Array.isArray(b)?b:[];
  if((mgIdd(l)||!l.length)&&(mgIdd(r)||!r.length)&&(l.length||r.length)){
   const key=x=>String(x.id),mB=new Map(),mL=new Map(),mR=new Map();Ba.forEach(x=>{if(mgObj(x)&&x.id!=null)mB.set(key(x),x)});l.forEach(x=>mL.set(key(x),x));r.forEach(x=>mR.set(key(x),x));
   const out=[];
   r.forEach(ri=>{const id=key(ri),li=mL.get(id),bi=mB.get(id);
    if(li){out.push(mg3(bi,li,ri));return}
    if(bi&&mgEq(bi,ri))return;               /* deleted here, untouched there: stays deleted */
    out.push(mgCl(ri))});                      /* new there, or edited there after being deleted here: kept */
   l.forEach((li,i)=>{const id=key(li);if(mR.has(id))return;const bi=mB.get(id);
    if(bi&&mgEq(bi,li))return;               /* deleted there, untouched here: stays deleted */
    out.splice(Math.min(i,out.length),0,mgCl(li))});   /* new here (or edited here): kept, near its place */
   return out}
  if(mgPrim(l)&&mgPrim(r)){const inB=new Set(Ba.map(x=>JSON.stringify(x))),inR=new Set(r.map(x=>JSON.stringify(x))),inL=new Set(l.map(x=>JSON.stringify(x)));
   const out=l.filter(x=>!(inB.has(JSON.stringify(x))&&!inR.has(JSON.stringify(x))));
   r.forEach(x=>{const j=JSON.stringify(x);if(!inL.has(j)&&!inB.has(j))out.push(x)});
   return out}
  return mgCl(l)}
 return mgCl(l)}


