const PZF='a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function pzModals(){return [...document.querySelectorAll('[aria-modal="true"]')].filter(m=>!m.closest("#obtr")&&!m.closest("#app")&&m.getClientRects().length)}
function pzTopM(){const a=pzModals();return a[a.length-1]||null}
