document.addEventListener("focusin",e=>{try{if(e.target&&e.target.closest&&!e.target.closest('[aria-modal="true"]'))pzPrevF=e.target}catch(x){}},true);
document.addEventListener("keydown",e=>{const m=pzTopM();if(!m)return;
 if(e.key==="Tab"){const f=[...m.querySelectorAll(PZF)].filter(x=>x.getClientRects().length);if(!f.length){e.preventDefault();return}
  const i=f.indexOf(document.activeElement);if(e.shiftKey){if(i<=0){e.preventDefault();f[f.length-1].focus()}}else if(i===-1||i===f.length-1){e.preventDefault();f[0].focus()}}
 else if(e.key==="Escape"){if(m.closest(".twov"))return;e.preventDefault();try{pzBack()}catch(x){}}},true);
