 try{const L=preRvL(),f=L[L.length-1];if(f&&(preSo(f.id)||soXpConf(f.id)))out.push([soXpAny()?"Final review sign-off":"Final review sign-off (recorded by me)",f.n+": "+preSoTxt(f.id)])}catch(e){}
